(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-latent-consistency-models-synthesizi-2023"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-1\">一 · 一个凌晨两点的队列：步数如何变成延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-2\">二 · 像素空间一致性模型的显存墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-3\">三 · 少步蒸馏的工程约束：端点、点对与批调度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-4\">四 · 真正的瓶颈不在学生前向，而在 VAE 解码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-5\">五 · 为什么非改不可：步数是乘在成本前面的系数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-6\">六 · 在线出图队列里，先触顶的往往不是采样器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-7\">七 · 请求形态：分辨率与步数构成二维负载格</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-8\">八 · 批大小与 CFG：有效批翻倍的真实代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-9\">九 · 步数档位作为 SLO 的调节阀</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-10\">十 · 长尾：解码阶段与高分辨率请求</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-11\">十一 · 负载反过来限制方案：批调度的可行域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-12\">十二 · 档位队列的边界条件：负载如何反向锁死少步方案</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-13\">十三 · 学生网络的算子骨架与精度落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-14\">十四 · FP16/BF16 的分工：为什么控制面不能降</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-15\">十五 · FP8 与 NVFP4：格式选择与缩放因子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-16\">十六 · Blackwell 特性如何改变这条链路的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-17\">十七 · 端点误差如何被数值精度放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-18\">十八 · 精度档位的工程落地顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-19\">十九 · 少步蒸馏落进 Blackwell 精度档位时的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-20\">二十 · 显存账本的三层结构：权重、激活、解码峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-21\">二十一 · 没有 KV cache，但有等价的可复用张量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-22\">二十二 · 带宽瓶颈的位置：权重读取与解码写回</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-23\">二十三 · 分页、压缩、复用、卸载的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-24\">二十四 · 一个可复算的显存预算例</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-25\">二十五 · 失败模式与监控信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-26\">二十六 · 显存账本：解码峰值、CFG 翻倍与批大小的真实边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-27\">二十七 · 从“步数档位”到“批内异构”：连续批处理的粒度问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-28\">二十八 · Chunked prefill 的类比：把 CFG 批合并拆成可抢占的块</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-29\">二十九 · 优先级与抢占：超时请求的降档路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-30\">三十 · 分离式预填/解码的映射：学生前向与 VAE 解码分池</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-31\">三十一 · 尾延迟怎么压：批内同步点与解码抖动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-32\">三十二 · 调度器要记录什么：失败模式信号与档位决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-33\">三十三 · 解码显存封顶下的档位调度与抢占边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-34\">三十四 · 从单卡少步前向到多卡切分：为什么一致性模型也要谈并行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-35\">三十五 · NVLink 5 与 NVSwitch：集合通信的物理底座</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-36\">三十六 · NIXL 传输：把显存与解码结果搬对地方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-37\">三十七 · 通信何时成为瓶颈：三个判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-38\">三十八 · 与调度、解码的耦合：并行不是独立旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-39\">三十九 · 精度塌陷：少步档位下的端点误差放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-40\">四十 · OOM：解码峰值而非前向峰值决定批大小</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-41\">四十一 · 批抖动：聚批粒度与档位切换的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-42\">四十二 · 尾延迟与静默降级：SLO 违约的两种面貌</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-43\">四十三 · 监控面与回滚顺序：把失败模式映射到可执行动作</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-44\">四十四 · 少步蒸馏服务化的失效边界与诊断回路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-45\">四十五 · 基准口径的三层结构：模型档、硬件档、服务档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-46\">四十六 · batch 与并发的两种读法：静态聚批与连续批处理</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-47\">四十七 · 指标族：TTFT/TPOT 在扩散服务里的映射与失真</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-48\">四十八 · 哪些提升不可比：四类典型误读</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-49\">四十九 · 容量规划的读法：从解码峰值反解批上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-50\">五十 · 量化与 Blackwell 档位：材料未覆盖的部分如何标注</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-51\">五十一 · 基准口径的失效边界：少步蒸馏数字在什么条件下不可比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-52\">五十二 · 迁移到非 U-Net 骨干：一致性约束的可加性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-53\">五十三 · 迁到流匹配与整流采样器：端点定义的改写</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-54\">五十四 · 迁到视频与多帧生成：时间维的一致性约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-55\">五十五 · 迁到量化部署：数值精度与一致性损失的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-56\">五十六 · 规模上限：步数下限与分辨率上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-latent-consistency-models-synthesizi-2023-sec-57\">五十七 · 不适用的边界：何时不该用这套方案</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:590px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求到达后按分辨率与步数档位入队，调度器把同档请求聚成批以摊薄权重读取。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">文本编码器给出条件嵌入，与空条件嵌入拼成 CFG 批，一次前向同时算条…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">学生一致性网络在潜空间上做一次（或少步）前向，从噪声潜变量直接映射到轨…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">端点潜变量送入 VAE 解码器还原为像素图像，解码显存峰值与分辨率平方…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">结果回传并按 SLO 统计端到端延迟，超时请求进入重试或降档队列。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-1\">一 · 一个凌晨两点的队列：步数如何变成延迟</h3>\n<p>设想一个面向电商的在线图像生成服务：晚高峰过后，运营系统在凌晨两点批量提交商品场景图，请求以每秒若干条的速率进入网关，每条请求携带一段文本提示、一个分辨率档位（例如 1024×1024 潜空间档）和默认采样步数。调度器把同档请求聚成批，文本编码器产出条件嵌入，与空嵌入拼成 CFG 批送入教师潜扩散 U-Net，采样器执行数十步迭代，最后 VAE 解码回像素。问题不在于单条请求能不能跑完，而在于队列的排空速率被采样步数直接卡住：单请求的前向次数等于步数乘以 CFG 的批合并倍数，端到端延迟里学生/教师网络的迭代时间占绝对主导，VAE 解码只在末尾出现一次。步数每翻一倍，单请求算力近似线性翻倍，队列延迟随之线性恶化，而 GPU 的权重读取在每步都要重复一遍——同一份 U-Net 权重被读数十次，算力利用率被固定开销稀释。这就是这篇论文之前推理栈的主流形态：<strong>多步迭代采样 + CFG 批合并 + 末尾 VAE 解码</strong>，三者共同决定了服务的吞吐上限与显存峰值。</p>\n<p>把这条链路写成代价模型，单请求的网络前向次数为</p>\n<div class=\"formula\">$$N_{\\text{fwd}} = S \\cdot (1 + \\mathbb{1}_{\\text{CFG}}),\\qquad T_{\\text{e2e}} \\approx N_{\\text{fwd}}\\cdot t_{\\text{step}} + t_{\\text{VAE}} + t_{\\text{queue}}$$</div>\n<p>其中 $S$ 是采样步数，$t_{\\text{step}}$ 是单步前向在给定批大小下的耗时。$S$ 取数十时，$N_{\\text{fwd}}$ 轻松过百；即便 $t_{\\text{step}}$ 被批摊薄，$S$ 仍是乘在总时间前面的系数。工程上想让队列排空变快，要么加大批（受显存限制），要么降 $S$——而后者正是这篇论文要动的那颗螺丝。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-2\">二 · 像素空间一致性模型的显存墙</h3>\n<p>在潜一致性模型之前，一致性模型已经在像素空间给出了一步映射的思路：训练一个网络，把扩散轨迹上任意一点直接映射到轨迹端点，推理时一次前向即可出图。这个思路在低分辨率上成立，但搬到高分辨率就撞上显存与算力的墙。像素空间意味着网络输入输出都是 $H\\times W\\times 3$ 的张量，高分辨率下激活显存随分辨率平方增长，U-Net 的中间特征图数量级迅速膨胀；训练时批大小被激活显存压到很小，推理时单张图的解码与中间激活同样吃紧。更关键的是，像素空间的一致性模型无法直接复用预训练潜扩散模型的权重与 VAE 结构——它要求在像素域重新训练一套骨干，等于放弃已经调好的教师，训练成本与画质风险都要重新承担。</p>\n<p>用显存估算说明这道墙：若中间激活按 $B\\cdot C\\cdot H\\cdot W$ 计，分辨率从 256 提到 1024，$H\\cdot W$ 放大 16 倍，同一批大小下激活显存同比放大。像素空间一致性模型因此陷入两难：批小则吞吐低、权重读取摊不薄；批大则直接 OOM。这正是论文要解决的现场——<strong>一步映射的思路是对的，但落地的空间选错了</strong>。潜空间把 $H\\times W$ 压到 $h\\times w$（VAE 下采样后），激活显存按比例下降，同时教师权重可以直接复用，训练只需在潜空间上做蒸馏。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-3\">三 · 少步蒸馏的工程约束：端点、点对与批调度</h3>\n<p>把步数从数十压到个位数，不是把采样器步长调大那么简单：步长放大会让离散化误差累积，画质塌陷。论文的做法是在教师多步轨迹上构造相邻时间步的点对，约束学生对两点的预测指向同一端点。训练损失写成</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\mathrm{CD}}(\\theta)=\\mathbb{E}_{\\mathbf{z}_{t_{n+1}},\\mathbf{z}_{t_n}}\\left[d\\left(f_\\theta(\\mathbf{z}_{t_{n+1}},t_{n+1}),\\ f_{\\theta^{-}}(\\hat{\\mathbf{z}}_{t_n},t_n)\\right)\\right],\\quad \\hat{\\mathbf{z}}_{t_n}=\\mathbf{z}_{t_{n+1}}-(t_{n+1}-t_n)\\,\\Phi(\\mathbf{z}_{t_{n+1}},t_{n+1})$$</div>\n<p>这里 $\\Phi$ 是教师的一步估计，$\\hat{\\mathbf{z}}_{t_n}$ 由相邻时间步差与教师输出构造，$f_{\\theta^{-}}$ 是滑动平均更新的目标网络。工程含义有三层：其一，端点估计精度决定少步档位的画质上限，步数越少，相邻点间隔越大，端点误差累积越明显，所以 1 步档与少数步档要分开评估；其二，训练全程冻结教师，只训练学生，训练显存由潜变量分辨率与 U-Net 激活决定，高分辨率档需要梯度累积或分片才能撑住批大小；其三，推理侧学生一次前向即出端点潜变量，$N_{\\text{fwd}}$ 从数十降到个位数，单请求算力近似线性下降——但这不是免费的，画质以端点误差衡量，档位选择变成画质与延迟的显式权衡。</p>\n<p>具体到服务调度：请求按分辨率与步数档位分组入队，同档聚批以摊薄权重读取；CFG 开启时条件与非条件前向拼成一个批，有效批翻倍，显存与吞吐要在档位间取舍；超时请求降档到更少步数或重试，监控端到端延迟、批大小与显存峰值作为主要失败模式信号。一个可操作的伪代码思路是：入队时读分辨率档与 SLO 余量，若队列积压超过阈值则把该批的步数档从少数步降到 1 步，用画质换排空速率；出队后按档位统计 P99 延迟，反推下一窗口的批大小上限。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-4\">四 · 真正的瓶颈不在学生前向，而在 VAE 解码</h3>\n<p>少步蒸馏把学生前向次数压下来之后，链路的显存峰值结构发生了变化：学生一次前向的激活显存有限，而 VAE 解码的显存峰值随分辨率平方增长，往往比学生前向更早触顶。这意味着按学生前向显存估算批大小会高估容量——调度器以为还能塞两条请求，实际在解码阶段就 OOM。工程判断是：<strong>批大小上限应由解码阶段的显存峰值反推</strong>，而不是由 U-Net 前向的激活估算。CFG 批合并让有效批翻倍，这个倍数必须计入显存与延迟预算，否则 SLO 违约会以超时率的形式暴露。</p>\n<table class=\"mini\"><thead><tr><th>链路阶段</th><th>显存随规模的变化</th><th>对批大小的约束</th><th>服务化动作</th></tr></thead><tbody><tr><td>学生一致性前向</td><td>随潜变量分辨率与批大小增长</td><td>中等，通常不是首个触顶点</td><td>按档位设批上限</td></tr><tr><td>CFG 批合并</td><td>有效批翻倍，显存同比翻倍</td><td>强约束，需显式开关</td><td>高负载时关合并或降档</td></tr><tr><td>VAE 解码</td><td>随分辨率平方增长</td><td>实际瓶颈，常最先触顶</td><td>按解码峰值反推批大小</td></tr></tbody></table>\n<p>这张表解释了一个常见误判：团队看到学生一次前向很快，就把批开大，结果解码阶段显存爆掉、请求重试，端到端延迟反而更差。正确做法是把解码峰值当作容量规划的第一约束，学生前向的节省用来换更小的批或更多的并发档位，而不是无脑加批。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-5\">五 · 为什么非改不可：步数是乘在成本前面的系数</h3>\n<p>回到凌晨两点的队列。多步采样栈的痛点可以归成三条：延迟上，$S$ 是乘在 $t_{\\text{step}}$ 前面的系数，降 $S$ 是唯一能数量级改善端到端延迟的杠杆；吞吐上，每步都要重读一遍 U-Net 权重，固定开销被步数放大，算力利用率上不去；显存上，像素空间方案在高分辨率下激活爆炸，潜空间方案则把瓶颈转移到 VAE 解码。少步蒸馏把 $S$ 从数十压到个位数，前向次数下降一到两个数量级，单请求算力与队列延迟同步下降，同时保留 CFG 批合并与 VAE 解码的既有服务形态，接入批调度与档位降级不需要重写链路。</p>\n<p>但材料没有给出数据集与硬件实测，量化方案（NVFP4/FP8）与 Blackwell 档位上的数值精度、容量结论无法从本文推断；KV 类缓存不适用于这条链路，分离式预填/解码也未涉及。可核验的机制性结论只有一条：把采样从教师的多步迭代压到个位数前向，单请求算力随步数近似线性下降，画质由一致性损失的端点误差约束。对推理工程师而言，这意味着改造的起点是<strong>把步数档位做成调度器的一等公民</strong>——按分辨率与步数分组入队、按解码显存峰值定批、按 SLO 余量触发降档，而不是先去做量化或换硬件。步数这颗螺丝拧下来，后面的容量规划才有意义。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-6\">六 · 在线出图队列里，先触顶的往往不是采样器</h3>\n<p>一个高分辨率文生图服务在高峰时段的典型形态是：请求按分辨率档位入队，调度器把同档请求聚成批，文本编码器给出条件嵌入、与空嵌入拼成 CFG 批，送进潜扩散 U-Net 迭代数十步，最后 VAE 解码回像素。这套栈的痛点不在单步算子，而在步数把整条链路的时间与显存预算同时锁死。单请求前向次数与采样步数成正比，队列延迟随步数线性抬升；而批大小的上限并不由 U-Net 前向决定——VAE 解码的显存峰值随分辨率平方增长，高分辨率档位上解码阶段往往比采样阶段更早触顶，于是“多聚一点批来摊薄权重读取”的常规手段在解码处失效。CFG 批合并又把有效批翻倍，条件与非条件分支共享同一批维度，显存与延迟预算必须按双份计。这三件事叠加，使服务在分辨率升高时只能靠缩小批、拉长队列来维持，吞吐与 SLO 同时被压。</p>\n<p>旧方案的另一条路是像素空间一致性模型：在像素上直接学一步映射，绕开多步迭代。但它的边界恰恰在分辨率上暴露——像素空间的一致性蒸馏要承载全分辨率张量的激活，显存与算力随分辨率平方增长，高分辨率下根本撑不住训练与部署，更无法复用预训练潜扩散模型已经学好的潜空间表征。于是出现一个尴尬的夹层：多步潜扩散画质可用但步数代价高，像素空间少步方案步数低但上不了高分辨率。推理侧真正缺的不是“更快的采样器”，而是一个能在潜空间里把教师多步轨迹压成个位数前向、同时保留既有 CFG 批合并与 VAE 解码服务形态的方案。潜一致性蒸馏正是填这个夹层：教师冻结，学生在同一潜空间复用骨干，用轨迹相邻时间步的点对做自一致约束，</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\mathrm{CD}}(\\theta)=\\mathbb{E}_{\\mathbf{z}_{t_{n+1}},\\mathbf{z}_{t_n}}\\left[d\\left(f_\\theta(\\mathbf{z}_{t_{n+1}},t_{n+1}),\\ f_{\\theta^{-}}(\\hat{\\mathbf{z}}_{t_n},t_n)\\right)\\right]$$</div>\n<p>学生一次前向即从噪声潜变量映射到端点。代价随之转移：前向次数下降一到两个数量级，但画质上限被教师轨迹的端点估计精度钉住，步数越少误差累积越明显；而部署侧的真实瓶颈并未消失，只是从采样阶段挪到了解码阶段与 CFG 开关上。</p>\n<table class=\"mini\"><thead><tr><th>代价项</th><th>旧多步栈</th><th>潜一致性少步栈</th><th>服务化表现</th></tr></thead><tbody><tr><td>单请求前向次数</td><td>数十步</td><td>个位数（1 步与少数步档）</td><td>队列延迟近似线性下降</td></tr><tr><td>显存峰值位置</td><td>采样激活为主</td><td>VAE 解码为主，随分辨率平方增长</td><td>高分辨率档批大小被解码卡住</td></tr><tr><td>CFG 批合并</td><td>有效批翻倍</td><td>同样翻倍，未消除</td><td>显存与延迟预算按双份计</td></tr><tr><td>画质约束</td><td>步数换画质</td><td>端点误差决定少步下限</td><td>降档换吞吐需监控超时率</td></tr></tbody></table>\n<p>失效条件因此很具体：按学生前向的激活显存去估算批大小会系统性高估容量，因为解码峰值先到；把少步档的画质结论直接外推到更高分辨率或量化部署，材料并未给出对应实测，NVFP4/FP8 在权重与激活上的数值精度需另行验证；CFG 批合并若未计入显存与延迟预算，SLO 违约会以超时请求堆积的形式出现。调度器的可用手段只剩按分辨率与步数档位聚批、超时降档到更少步数或重试，监控端到端延迟、批大小与显存峰值三个信号来触发降档——这套机制能兜住流量，但兜不住“解码显存峰值随分辨率平方增长”这条硬约束，容量规划必须从解码侧反推批上限，而不是从采样侧。</p>\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-7\">七 · 请求形态：分辨率与步数构成二维负载格</h3>\n<p>LCM 服务化后，请求不再是“一张图”这样一个标量，而是落在（分辨率档位 × 步数档位）构成的二维格上。分辨率决定潜变量张量的空间尺寸，进而决定学生前向的激活显存与 VAE 解码的峰值显存；步数档位决定单请求调用学生网络的次数，1 步档与少数步档在算力上差出数倍。这两个维度不是独立的：高分辨率请求通常被允许用更少步数以保住 SLO，而低分辨率请求可以承受多步以换取画质。调度器如果只按到达顺序排队，就会把高分辨率少步请求和低分辨率多步请求混在同一批里，批内张量形状不一致，只能拆批，摊薄权重读取的收益立刻消失。</p>\n<p>可核查的测量口径是：对每个（分辨率，步数）格记录到达率 λ、批内平均样本数 B、单批学生前向耗时 T_fwd、单批 VAE 解码耗时 T_dec、端到端延迟分位数（p50/p90/p99）与显存峰值。到达率用固定窗口计数，延迟从请求入队时刻算到结果回传时刻，显存峰值取解码阶段的 cudaMemGetInfo 采样最大值而非学生前向阶段的估值。缺少这五个量，任何“吞吐提升了多少”的说法都无法归因到具体档位。</p>\n<p>具体例子：同一台机器上，1024×1024 档位的解码显存峰值按分辨率平方增长，其批大小上限远低于 512×512 档位；若把两档混排，1024 档的显存峰值会强制整批缩小，512 档的请求被迫陪着降批，吞吐被高分辨率请求拖累。按档位分队列是让负载形态反过来约束方案的第一条工程判断。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-8\">八 · 批大小与 CFG：有效批翻倍的真实代价</h3>\n<p>CFG 批合并把条件嵌入与空嵌入拼成一个批，一次前向同时算两个分支。这在实现上把有效批大小翻倍：调度器以为批大小是 B，实际送进学生网络的张量是 2B。显存占用随批大小线性增长，于是显存预算必须按 2B 计算，而不是 B。更隐蔽的代价在延迟侧：CFG 合并让单次前向的计算量翻倍，但省掉了第二次前向的权重读取与启动开销，所以在权重读取主导的小批场景下合并是净收益，在激活显存主导的大批场景下合并反而先触顶。</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx M_{\\text{weights}} + 2B \\cdot \\big(m_{\\text{act}}(H,W) + m_{\\text{latent}}(H,W)\\big) + M_{\\text{dec}}(H,W)$$</div>\n<p>其中 $m_{\\text{act}}$ 是学生 U-Net 单样本激活显存，$m_{\\text{latent}}$ 是潜变量本身，$M_{\\text{dec}}$ 是解码阶段峰值。这个式子给出的判据是：当 $2B \\cdot m_{\\text{act}}$ 接近 $M_{\\text{dec}}$ 时，CFG 合并与批大小扩张会同时挤压显存，必须二选一。可核查口径是分别测“CFG 合并 + 批大小 B”与“CFG 拆开 + 批大小 2B”两种配置下的端到端延迟与显存峰值，比较的是同一有效样本数下的吞吐，而不是同一批大小下的吞吐。</p>\n<p>具体例子：某档位下学生前向显存尚有余量，但 VAE 解码峰值已经逼近上限；此时把 CFG 合并打开会让有效批翻倍，解码阶段直接 OOM，调度器被迫把批大小砍半，端到端吞吐反而下降。这个失败模式在只按学生前向显存估算容量的部署里反复出现。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-9\">九 · 步数档位作为 SLO 的调节阀</h3>\n<p>少步蒸馏把采样从教师数十步压到个位数，单请求前向次数近似线性下降，这是 LCM 对服务化最直接的贡献。但“个位数”不是一个点，而是一组档位：1 步、2 步、4 步等。步数越少，端点估计误差累积越明显，画质上限受教师轨迹端点精度约束。于是步数档位天然成为 SLO 的调节阀：队列积压时把请求降到更少步数档位换取吞吐，队列空闲时升档换画质。</p>\n<p>可核查的测量口径必须把画质纳入：每个步数档位记录端点误差（学生输出与教师多步端点之间的距离）、人工或自动画质评分、端到端延迟分位数与超时率。只报延迟不报画质，等于把降档说成免费午餐。降档策略的判据是延迟 p99 超过 SLO 阈值时触发，触发后记录降档请求比例与降档后的画质分布，才能判断降档是否真的救了 SLO 而不是把违约换成了画质投诉。</p>\n<p>具体例子：一个 4 步档请求在队列中等待超过阈值，调度器把它改派到 1 步档；单请求前向次数降到四分之一，队列延迟下降，但该请求的端点误差上升。若监控只记录延迟，这次降档看起来是纯收益；把端点误差一并记录，才能看到降档的代价落在哪一档画质上。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-10\">十 · 长尾：解码阶段与高分辨率请求</h3>\n<p>LCM 推理链路里，学生前向是一次（或少步）潜空间映射，VAE 解码则是把潜变量还原为像素。解码显存峰值随分辨率平方增长，在高分辨率档位上往往比学生前向更早触顶。这意味着延迟长尾不由学生前向决定，而由解码决定：一批请求里只要混入一个高分辨率样本，整批的解码阶段就被拉长，p99 延迟被这一个样本主导。</p>\n<p>可核查口径是把延迟拆成三段分别统计：文本编码与 CFG 拼批、学生前向、VAE 解码。长尾分析要看每一段的 p99 与批内最大样本的对应关系，而不是只看端到端 p99。若解码段 p99 显著高于前向段 p99，说明批内分辨率方差是长尾来源，解法是按分辨率分队列而不是加大批大小。</p>\n<p>具体例子：同批内 512 与 1024 混排，1024 样本的解码耗时把整批 p99 拉高，而学生前向段因为批大小被显存限制反而平稳。此时提升吞吐的正确动作是拆批分档，而不是继续合并 CFG 或扩大批大小——后者只会让解码峰值更早触顶。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-11\">十一 · 负载反过来限制方案：批调度的可行域</h3>\n<p>负载形态不只塑造调度，还反过来限制方案本身。批大小受潜变量分辨率与 U-Net 激活显存约束，CFG 合并使有效批翻倍，解码峰值随分辨率平方增长，这三条共同划出一个可行域：在给定硬件档位上，每个（分辨率，步数）格能支撑的最大批大小是有限的。训练侧同样受此约束——训练在潜空间进行以避免像素空间显存爆炸，但批大小仍受潜变量分辨率与 U-Net 激活显存限制，高分辨率需梯度累积或分片。</p>\n<p>可核查口径是容量表：对每个档位记录最大可行批大小、对应显存峰值、端到端吞吐与 p99 延迟，并标注该批大小是由学生前向显存还是解码显存卡住的。这张表是容量规划的唯一可信输入；任何按“学生前向显存估算批大小”的做法都会高估容量，因为解码阶段往往先触顶。</p>\n<p>具体例子：某档位按学生前向显存估算可支撑批大小 B，实际部署时解码阶段在 B/2 就触顶；容量表若只记估算值，规划出的副本数会不足，SLO 在高峰违约。把“卡住批大小的阶段”写进容量表，才能让扩容决策落在正确的瓶颈上。</p>\n<p>材料未给出 NVFP4/FP8 量化与 Blackwell 档位的实测，因此上述可行域在 SM100/SM103 上的具体数值无法从本文推断；可迁移的工程判断是：先测解码峰值再定批大小，先分档再谈合并，先记端点误差再谈降档。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-12\">十二 · 档位队列的边界条件：负载如何反向锁死少步方案</h3>\n\n<p>潜一致性模型把单请求前向次数从教师数十步压到个位数，这条结论只在“请求可聚批、显存够解码”的前提下成立。负载形态一旦偏离这个前提，少步带来的算力节省会被调度开销与解码峰值吃掉。可核查的测量口径必须把三件事分开记：学生前向的批内延迟、VAE 解码的显存峰值、以及从入队到回传的端到端延迟。前两者是方案自身的代价，后者才是 SLO 的判据。若只统计前向时间，会系统性低估高分辨率档位的真实排队时长——解码阶段往往比学生前向更早触顶，批大小在解码处被卡住，前向再快也无法提升吞吐。</p>\n\n<p>负载对方案的反向塑造体现在档位设计上。请求按分辨率与步数档位入队，同档聚批以摊薄权重读取；但档位越细，队列越容易碎片化，小批导致权重读取的固定开销占比上升，单请求算力反而回升。这里存在一个可写出的权衡：设批大小为 $B$、单批固定开销为 $c_0$、每请求边际算力为 $c_1$，则每请求平均算力为 $c_0/B + c_1$，而解码显存峰值随分辨率平方增长、随 $B$ 线性增长，记作 $M(B,r)\\propto B\\cdot r^2$。容量约束给出 $B\\le B_{\\max}(r)$，于是档位粒度必须在“聚批摊薄”与“碎片化”之间取平衡。CFG 批合并是这条公式里最直接的开关：它把有效批翻倍，$B$ 在显存预算中按两倍计，吞吐收益与 SLO 违约风险同时放大，未计入预算就会在高峰时段集中暴露。</p>\n\n<table class=\"mini\"><thead><tr><th>测量项</th><th>口径</th><th>失效信号</th></tr></thead><tbody><tr><td>端到端延迟</td><td>入队时间戳到结果回传，按档位分桶统计分位数</td><td>高分位抬升而中位数平稳，说明长尾由解码峰值或降档重试造成</td></tr><tr><td>批大小分布</td><td>实际执行批而非入队批，区分 CFG 合并前后</td><td>实际批长期低于档位上限，说明队列碎片化或显存先触顶</td></tr><tr><td>显存峰值</td><td>解码阶段峰值单独记录，与学生前向峰值分开</td><td>按前向峰值估算容量会高估可承载批大小</td></tr><tr><td>超时率与降档率</td><td>超时请求中降档与重试的比例</td><td>降档率上升意味着少步档位画质下限被反复触碰</td></tr></tbody></table>\n\n<p>长尾请求是这套方案最脆弱的边界。少步蒸馏的画质上限受教师轨迹端点估计精度约束，步数越少误差累积越明显；当调度器为压队列把请求降到更少步数档位，画质下降不是均匀发生的，而是集中在端点估计误差大的样本上——这类样本往往也是重试与降档的主要来源，形成“降档—画质不达标—重试—队列再积压”的正反馈。可核查的做法是把降档率与重试率作为一阶指标而非事后统计，并在档位切换处记录端点误差的代理量（如相邻步预测距离），使画质下限的触碰可被定位到具体档位而非笼统归因于负载。材料未给出量化与 Blackwell 档位的实测，因此 NVFP4/FP8 下的数值精度不能从少步结论外推；容量规划只能以解码显存峰值与实测批大小分布为准，不能以学生前向的算力节省反推吞吐上限。</p>\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-13\">十三 · 学生网络的算子骨架与精度落点</h3>\n<p>潜一致性模型的学生骨干复用教师潜扩散 U-Net 的卷积与注意力结构，推理时只跑一次（或少步）前向。落到 Blackwell 上，这条前向链路的算子构成决定了精度策略：主体是 3×3/1×1 卷积、空间与通道注意力里的 GEMM、GroupNorm/SiLU 这类逐元素与归约算子，以及时间步嵌入的 MLP。GEMM 与卷积占算力大头，是 FP8/NVFP4 张量核心的用武之地；GroupNorm 的均值方差归约与 SiLU 是访存受限的小算子，量化收益低、数值敏感度高，通常保留 FP16/BF16。时间步嵌入经 MLP 后以仿射方式调制各层，这条通路的数值误差会被逐层放大，属于必须留在高精度的“控制面”。工程判断是：把量化预算集中在 GEMM/卷积，逐元素与归约算子走 BF16 旁路，形成混合精度图，而不是整网一刀切。</p>\n<p>以单次前向的算力账为例：设潜变量分辨率 H×W、通道 C，一层注意力的 QKV 投影是 (HW)×C 乘 C×3C 的 GEMM，卷积层则是 HW×C×C×9 量级的乘加。学生只跑一步，意味着这些算力只发生一次，而教师多步采样要重复数十次——步数压缩把总算力近似线性砍掉，剩下的单步算力就必须靠低精度张量核心进一步压低。代价侧：FP8 相对 BF16 把权重与激活的字节数减半，权重读取带宽减半，但激活显存峰值不因量化而下降（中间张量仍按元素数计），所以批大小仍受激活与 VAE 解码约束，量化只缓解权重侧带宽与算力，不解决解码显存。</p>\n<div class=\"formula\">$$\\text{GEMM}_{\\text{attn}}:\\ (HW)\\times C\\ \\cdot\\ C\\times 3C,\\qquad \\text{FLOPs}\\approx 2\\cdot HW\\cdot C\\cdot 3C$$</div>\n<p>逐项解释：HW 是潜变量空间位置数，C 是通道维，2 来自乘加各计一次。该式给出单层 QKV 投影的浮点运算量；把每层卷积、注意力、MLP 的同类项累加，就得到学生单步前向的总算力上界。量化把每次乘加的位宽从 16 降到 8 或 4，张量核心吞吐随之提升，但归约与逐元素算子不在此列，故实际加速比低于位宽比。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-14\">十四 · FP16/BF16 的分工：为什么控制面不能降</h3>\n<p>FP16 与 BF16 都是 16 位，差别在指数位与尾数位：FP16 尾数多、动态范围窄，BF16 指数位与 FP32 相同、尾数少。扩散类网络激活分布随层与时间步漂移，GroupNorm 的归约需要跨大量元素累加，BF16 的动态范围更适合承载这类中间量，避免溢出；而需要精细尾数的仿射调制系数、时间步嵌入，用 FP16 或直接 FP32 累加更稳。Blackwell 第五代 Tensor Core 对 FP16/BF16 的累加默认走 FP32，这一点对一致性蒸馏尤其关键：端点误差是相邻点预测之差，若累加精度不足，误差会被一致性损失放大成画质退化。</p>\n<p>具体机制：在 tcgen05 路径上，MMA 指令的累加器驻留 TMEM，累加精度可选 FP32；把累加器放在 TMEM 而非寄存器堆，是为了让 2-SM MMA 的两个 SM 共享同一块累加缓冲，减少跨 SM 的数据搬运。代价是 TMEM 容量有限，同时驻留的累加器数量约束了在飞 MMA 的深度；若一层里并行多个 MMA 争抢 TMEM，就得串行化，吞吐下降。例子：注意力里 QK^T 与 PV 两个 GEMM 若都要 FP32 累加并同时驻留 TMEM，TMEM 分配就成为该层的吞吐瓶颈，工程上常把二者分时复用同一块累加区。</p>\n<div class=\"formula\">$$\\hat{y}=\\sum_{k=1}^{K} a_k b_k,\\qquad \\text{err}\\le K\\cdot u\\cdot \\max_k|a_kb_k|$$</div>\n<p>逐项解释：K 是归约长度（GEMM 的 K 维或卷积的乘加深度），u 是累加所用浮点格式的单位舍入误差，max 项是该归约上的最大部分积量级。该式说明误差随归约长度线性增长、随部分积量级放大；K 很大的 GEMM（如通道数上千的投影）必须用 FP32 累加，否则 BF16 累加会让端点预测漂移。这也是 Blackwell 上“低精度乘、高精度加”策略的数值依据。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-15\">十五 · FP8 与 NVFP4：格式选择与缩放因子</h3>\n<p>FP8 有两种常见排布：E4M3 尾数多、范围窄，适合权重与激活；E5M2 范围大、尾数少，适合梯度类或动态范围大的量。推理侧通常权重与激活都用 E4M3，配合 per-tensor 或 per-channel 缩放因子把值域压进可表示区间。NVFP4 是 4 位浮点，尾数与指数位更少，必须依赖块级缩放（如每 16 或 32 个元素共享一个缩放因子）才能保住精度；块越小，缩放开销与元数据带宽越大，块越大，块内动态范围越难覆盖。这是一个显式的带宽—精度权衡。</p>\n<p>机制上，缩放因子在 GEMM 前对激活做一次乘、在累加后对结果做一次除，这两步是逐元素算子，访存受限；若块级缩放粒度太细，缩放元数据的读取会吃掉低精度带来的带宽收益。代价量化：FP8 把权重字节减半，权重读取带宽减半，但若每 16 元素一个 FP32 缩放因子，元数据相当于每元素额外 2 位，实际有效位宽从 8 升到约 10，带宽收益被侵蚀。例子：一个 C=320 的卷积层，per-channel 缩放只需 320 个因子，开销可忽略；换成 per-16-element 块缩放，因子数变成元素数/16，元数据带宽随激活尺寸线性增长，在高分辨率潜变量上不可忽视。</p>\n<div class=\"formula\">$$x_q=\\mathrm{round}\\!\\left(\\frac{x}{s}\\right),\\quad \\hat{x}=s\\cdot x_q,\\qquad s=\\frac{\\max|x|}{\\max_{\\text{fmt}}}$$</div>\n<p>逐项解释：s 是缩放因子，由该块内最大绝对值与该格式可表示的最大值之比决定；x_q 是量化后的整数/浮点码字，hat x 是反量化值。误差上界约为 s/2（最近舍入），故 s 越小误差越小，但 s 太小会截断大值造成饱和误差。块级缩放的本质是让每个块有自己的 s，用元数据换精度；NVFP4 的块必须足够小才能让块内动态范围可控。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-16\">十六 · Blackwell 特性如何改变这条链路的代价</h3>\n<p>tcgen05 是 Blackwell 的第五代 Tensor Core 指令族，MMA 由单个线程发起、累加器驻留 TMEM，把数据搬运从寄存器堆转移到张量内存，降低了寄存器压力，也让异步 MMA 与后续逐元素算子可以流水。2-SM MMA 让一对 SM 协同完成一个更大的 MMA，等效于把 MMA 的 N 维或 M 维翻倍，减少小 GEMM 的固定开销——这对学生网络里通道数不大、批内多请求并行的场景有用：把小批的多个请求在 MMA 维度上拼大，提高张量核心利用率。代价是 2-SM 协同要求两个 SM 的数据布局对齐，配对失败或负载不均时收益反转。</p>\n<p>对一致性模型推理的具体影响：学生单步前向的批由 CFG 批合并后的有效批决定，批越大，GEMM 的 M 维越大，越容易喂饱 2-SM MMA；但批大小受 VAE 解码显存峰值约束，高分辨率档位批很小，此时 2-SM MMA 的配对收益有限，反而 per-request 的固定开销占比上升。功耗侧：低精度张量核心在相同算力下功耗更低，但 TMEM 与缩放元数据的访存增加会抬高空载功耗，整卡功耗由算力与带宽共同决定，不能只看精度位宽。工程判断是：先按分辨率档位确定批大小，再决定是否启用 2-SM 配对与 FP8，而不是反过来。</p>\n<table class=\"mini\"><thead><tr><th>格式</th><th>典型用途</th><th>累加精度</th><th>主要代价</th></tr></thead><tbody><tr><td>BF16</td><td>GroupNorm、SiLU、时间步调制</td><td>FP32</td><td>算力未压缩，访存受限算子无收益</td></tr><tr><td>FP16</td><td>仿射系数、嵌入</td><td>FP32</td><td>动态范围窄，需防溢出</td></tr><tr><td>FP8 E4M3</td><td>卷积/注意力 GEMM 权重与激活</td><td>FP32</td><td>缩放元数据带宽、离群值饱和</td></tr><tr><td>NVFP4</td><td>权重块量化</td><td>FP32</td><td>块级缩放元数据、块内动态范围</td></tr></tbody></table>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-17\">十七 · 端点误差如何被数值精度放大</h3>\n<p>一致性损失约束的是相邻两点预测之差，端点由教师多步求解器给出。数值精度的影响不在单点绝对误差，而在相邻点误差的相关性：若两个相邻时间步的前向用了相同的量化方案与缩放因子，误差高度相关，差值时部分抵消；若两点因批合并或调度落在不同精度档位（例如一步档用 FP8、少数步档用 BF16），误差不相关，差值被放大，一致性约束反而学到噪声。这是混合精度部署里容易被忽略的失败模式。</p>\n<p>机制上，学生一次前向输出端点潜变量，端点误差经 VAE 解码放大为像素误差；VAE 解码器本身若量化，误差再叠一层。代价侧：解码显存峰值随分辨率平方增长，是批大小的实际瓶颈，量化解码器能减权重带宽但不减激活显存，故对批大小帮助有限。例子：同一批请求里，若调度器把部分请求降到一步档、部分留在少数步档，两档若共用同一份量化权重则误差相关，若分档加载不同精度权重则显存翻倍、批容量减半——这是一个必须在档位设计时定死的取舍。</p>\n<div class=\"formula\">$$\\Delta=\\left\\|f_\\theta(z_{t_{n+1}},t_{n+1})-f_{\\theta^-}(\\hat{z}_{t_n},t_n)\\right\\|,\\qquad \\hat{z}_{t_n}=z_{t_{n+1}}-(t_{n+1}-t_n)\\Phi(z_{t_{n+1}},t_{n+1})$$</div>\n<p>逐项解释：Delta 是相邻点预测距离，即一致性损失的核心量；z 是潜变量，t 是时间步，Phi 是教师求解器给出的一步估计方向，(t_{n+1}-t_n) 是步长。数值上，Phi 的估计精度决定 hat z 的准确度，而 hat z 又作为学生目标网络的输入；若 Phi 用低精度算，端点偏移直接进入损失，学生学到的映射偏离真实轨迹端点。故教师侧的一步估计应保持高精度，学生侧才谈量化。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-18\">十八 · 精度档位的工程落地顺序</h3>\n<p>落地顺序应是：先固定教师一步估计与端点构造的精度（FP32/BF16），保证监督信号干净；再对学生 GEMM 做 FP8 逐层替换，用端点误差与解码后画质做验收，逐层回退不合格层；最后才考虑 NVFP4 权重块量化，且只用于访存受限、对误差不敏感的层。每步都要在目标分辨率档位上测批大小与显存峰值，因为解码显存峰值往往比学生前向更早触顶，量化学生网络不会解锁更大的批。</p>\n<p>监控侧应记录每档的端点误差代理量（相邻点距离或与教师端点的偏差）、批大小、显存峰值与端到端延迟；超时触发降档时，降档改变的是步数而非精度，避免精度档位切换引入不相关误差。功耗上，FP8 与 NVFP4 在相同批下降低算力功耗，但若因精度回退导致部分层留在 BF16，混合图的调度开销会抵消部分收益。最终判断落在具体机制上：一致性模型的少步收益来自前向次数，量化收益来自每次前向的位宽，两者相乘才是 Blackwell 上的单请求总算力下降；而批容量由 VAE 解码显存决定，与量化基本解耦，容量规划必须把这两条账分开算。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-19\">十九 · 少步蒸馏落进 Blackwell 精度档位时的边界</h3>\n<p>潜一致性模型把前向次数压到个位数，代价从“算得多”转成“算得准”：端点误差被一致性损失直接暴露，任何量化噪声都会经 VAE 解码放大成可见伪影。学生单次前向的算术强度集中在 U-Net 的卷积与注意力，Blackwell 上走 tcgen05 的第五代 Tensor Core，FP16/BF16 输入配 FP32 累加是默认安全档；一旦把权重与激活降到 FP8，累加仍留 FP32，但输入舍入误差会沿相邻时间步点对的差值传播，因为损失约束的是两点预测之差，而非绝对端点。可写成误差上界的粗估：</p>\n<div class=\"formula\">$$\\|\\hat{\\mathbf{z}}_{t_n}-\\mathbf{z}^\\star\\| \\le \\underbrace{\\|\\mathbf{z}_{t_{n+1}}-(t_{n+1}-t_n)\\Phi\\|}_{\\text{端点估计}}+\\underbrace{\\epsilon_q\\cdot\\|f_\\theta\\|}_{\\text{量化舍入}}+\\underbrace{\\Delta t\\cdot\\|\\partial_t f\\|}_{\\text{步长离散}}$$</div>\n<p>三项里只有第二项受硬件档位控制：$\\epsilon_q$ 是 FP8 E4M3 的相对舍入量级，NVFP4 再低一档但需要块缩放与两级微缩放因子，权重侧尚可，激活侧在少步档位缺少校准样本时容易整段偏移。工程判断是：1 步档位优先 BF16 保画质，少数步档位可试 FP8 换吞吐，NVFP4 只在权重上试、激活留高精度，且必须按分辨率档位分别回归端点误差，不能把低分辨率结论外推。</p>\n<p>系统代价落在显存与带宽两侧。TMEM 作为 tcgen05 的累加器驻留张量内存，2-SM MMA 让两个 SM 协同吃更大的 tile，权重读取被摊薄，但学生网络的激活显存仍随潜变量分辨率平方增长，与 VAE 解码峰值叠加后才触顶。下表给出档位取舍的定性边界：</p>\n<table class=\"mini\"><thead><tr><th>档位</th><th>数值风险</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>BF16 + FP32 累加</td><td>低</td><td>权重带宽、Tensor Core 吞吐未满</td><td>批被解码显存卡死，算力闲置</td></tr><tr><td>FP8 权重/激活</td><td>中，端点差值放大</td><td>需校准，回归成本</td><td>少步档位伪影，CFG 批翻倍后更明显</td></tr><tr><td>NVFP4 权重</td><td>高，块缩放失配</td><td>微缩放因子额外读取</td><td>高分辨率档位画质下限不可核验</td></tr></tbody></table>\n<p>具体例子：一个 1024 分辨率档位、CFG 合并的批，学生前向在 BF16 下显存尚有余量，但 VAE 解码峰值先触顶，此时把学生降到 FP8 只省下前向那部分，对批大小几乎无益，反而引入端点误差；正确动作是把 CFG 拆开分两次前向或降档到更少步数，而不是压精度。材料未给出量化实测，故 Blackwell 上的精度档位只能按“先保解码显存、再谈 Tensor Core 利用率”的顺序排优先级。</p>\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-20\">二十 · 显存账本的三层结构：权重、激活、解码峰值</h3>\n<p>潜一致性模型的服务化显存账本必须按三层拆开算，不能用一个“模型多大”的数字糊过去。第一层是权重：学生复用教师 U-Net 骨干，参数在推理期只读，占用等于参数量乘每参数字节数，FP16 下每十亿参数约 2 GB，若走 NVFP4 则压到约 0.5 GB 量级——但材料明确未给出量化实测，这一层在 Blackwell 上只能按字节数定性估算，不能当作已验证容量。第二层是激活：学生一次前向在潜空间完成，激活峰值由潜变量分辨率、批大小与 U-Net 各层通道宽度共同决定，随批大小线性增长，这是训练期批大小的约束来源，也是推理期单次前向的固定开销。第三层是 VAE 解码：解码器把潜变量还原为像素，中间特征图尺寸随分辨率平方增长，显存峰值往往在学生前向之后才触顶，是高分辨率档位批大小的实际瓶颈。三层叠加才是单批驻留显存，任何按“学生前向显存”估算容量的做法都会系统性高估。</p>\n<p>把三层写成可复算的预算式，设批大小 $B$、潜变量空间分辨率 $H_l\\times W_l$、像素分辨率 $H\\times W$、潜通道数 $C_l$、每元素字节 $b$：</p>\n<div class=\"formula\">$$M_{\\text{batch}} \\approx \\underbrace{P\\cdot b}_{\\text{权重}}+\\underbrace{B\\cdot A(H_l,W_l)}_{\\text{学生激活}}+\\underbrace{B\\cdot D(H,W)}_{\\text{VAE 解码峰值}}$$</div>\n<p>其中 $A$ 与潜分辨率近似线性、$D$ 与像素分辨率近似平方。CFG 批合并时条件与非条件拼成一个批，有效批变为 $2B$，上式第二、三项都要乘 2——这是调度器最容易漏算的一项。举例：某高分辨率档位下解码峰值已接近单卡可用显存的一半，则即便学生前向只占很小一块，批大小也被解码项卡死在个位数；此时提高批大小摊薄权重读取的收益被解码显存抵消，吞吐不再随批线性上升。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-21\">二十一 · 没有 KV cache，但有等价的可复用张量</h3>\n<p>扩散/流匹配采样器不存在自回归解码那种逐 token 增长的 KV cache，材料也明确“KV 类缓存不适用”。但服务化里仍有三类可复用张量值得按 cache 的思路管理：文本编码器输出的条件嵌入（同一提示词跨请求可复用）、CFG 的空嵌入（全局常量，可预置为常驻张量）、以及少步档位下相邻步之间若走多步前向可复用的中间潜变量。条件嵌入的复用是纯收益：文本编码器只需在提示词首次出现时跑一次，后续同提示词请求直接命中，省掉一次编码器前向的算力与激活。空嵌入常驻则省掉每个 CFG 批里非条件分支的嵌入构造。这两项不改变解码峰值，但缩短了端到端延迟中的固定段。</p>\n<p>若档位从 1 步升到少数步，学生需要多次前向，中间潜变量在步间传递，其显存占用等于一个潜变量张量乘批大小，量级远小于解码峰值，但会拉长学生前向段的时间。调度上应把“步数档位”与“是否复用条件嵌入”解耦：命中嵌入缓存的请求可以走更少步档位而不增加排队时间，未命中的请求先付一次编码器成本再入学生队列。监控侧要分别记录嵌入命中率与解码峰值，前者影响延迟、后者影响批大小，混在一起统计会掩盖真正的瓶颈。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-22\">二十二 · 带宽瓶颈的位置：权重读取与解码写回</h3>\n<p>少步推理把计算量压到个位数前向之后，瓶颈从算力转向带宽。学生前向每层都要把权重从 HBM 读进 SM，批大小越小，权重读取被摊薄得越差，单请求的有效带宽开销越高；这正是聚批的经济学来源。以权重字节数 $P\\cdot b$、批大小 $B$、单次前向层数 $L$ 计，单批权重读取量近似 $L\\cdot P\\cdot b$，摊到每请求为 $L\\cdot P\\cdot b/B$，批越大单位请求的权重流量越低。Blackwell 的 HBM3e 提供高带宽，但带宽是共享资源，多档位并发时学生前向的权重流与 VAE 解码的特征图读写会互相挤压。</p>\n<p>解码段的带宽特征不同：它写回像素图像，输出字节随分辨率平方增长，且解码器中间特征图反复读写，属于带宽密集而非算力密集。工程判断是：学生前向段用大批摊薄权重，解码段用小块分批以压低峰值显存，两段用不同的批策略，中间用潜变量队列衔接。若强行用同一批大小贯穿两段，要么学生段批太小浪费带宽，要么解码段批太大触顶显存。HBM3e 容量换算按“容量 = 单卡 HBM 堆栈容量”直接读取硬件规格，预算式里的 $M_{\\text{batch}}$ 必须小于可用容量减去框架与通信缓冲的余量，余量在 NVLink 5 多卡张量并行下还要留出通信暂存。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-23\">二十三 · 分页、压缩、复用、卸载的取舍</h3>\n<p>分页在这里不是 KV 分页，而是潜变量与解码中间缓冲的分块管理：把解码器按空间切块，逐块解码并立即写回输出，块间不保留全分辨率中间张量，从而把解码峰值从“整图特征图”降到“单块特征图”。代价是块边界需要重叠像素以避免接缝，重叠区带来重复计算，吞吐略降但显存峰值显著下降，这是高分辨率档位扩容批大小的主要手段。压缩指权重与激活的数值精度压缩，NVFP4/FP8 在 Blackwell 上有硬件路径，但材料未给出该工作的量化实测，只能作为待验证项列出，不能写进容量承诺。</p>\n<p>复用已在第二节讲条件嵌入与空嵌入；卸载则针对权重：学生权重在请求间隙可驻留 HBM，也可在低峰期换出到主机内存，代价是换入时的带宽开销与首请求延迟抬升。工程判断是权重卸载只在批大小长期偏小、HBM 被解码峰值挤占时才划算，否则换入延迟会吃掉卸载省下的容量。四类手段的优先级应按瓶颈定位排序：解码峰值触顶先上分块解码，权重摊薄不足先加批，容量整体不足才考虑卸载与量化。每项都要在监控里对应一个可观测信号——解码峰值、单请求权重流量、换入次数——否则调优是盲调。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-24\">二十四 · 一个可复算的显存预算例</h3>\n<p>给定一个高分辨率档位，按预算式逐步填数：权重项取学生骨干参数量乘字节数（FP16 或 NVFP4 两档并列，后者标注未验证）；学生激活项按潜分辨率与批大小线性估算，系数由 U-Net 通道宽度决定，需在目标硬件上实测标定而非套用他卡数字；解码项按像素分辨率平方估算，同样需实测标定。CFG 开启时把激活与解码两项乘 2。把三项相加得到单批驻留，再用可用 HBM3e 容量减去框架与通信余量做比较，反解出最大批大小 $B_{\\max}$。</p>\n<table class=\"mini\"><thead><tr><th>项</th><th>缩放规律</th><th>CFG 影响</th><th>触顶顺序</th></tr></thead><tbody><tr><td>权重</td><td>与批无关，常数</td><td>不变</td><td>最先满足，非瓶颈</td></tr><tr><td>学生激活</td><td>随 $B$ 线性、随潜分辨率线性</td><td>×2</td><td>中批时触顶</td></tr><tr><td>VAE 解码峰值</td><td>随 $B$ 线性、随像素分辨率平方</td><td>×2</td><td>高分辨率档最先触顶</td></tr></tbody></table>\n<p>复算的要点是三项的缩放指数不同：权重是常数，激活线性，解码平方。分辨率翻倍时解码项约四倍增长，而激活项只约两倍，因此高分辨率档位的 $B_{\\max}$ 由解码项单独决定，学生前向的批容量余量被浪费。此时正确动作是分块解码把平方项降为线性项乘块数，再重解 $B_{\\max}$；若不做分块而直接降批，吞吐损失远大于分块带来的重叠计算损失。这个判断不依赖任何未给出的实测数字，只依赖缩放指数，因此可以在材料约束下给出确定的工程结论。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-25\">二十五 · 失败模式与监控信号</h3>\n<p>三类失败模式直接对应三层账本。其一，按学生前向显存估算批大小，忽略解码峰值随分辨率平方增长，容量被高估，表现为高分辨率档位频繁 OOM 或被迫运行时降批，SLO 抖动。其二，CFG 批合并未计入显存与延迟预算，有效批翻倍后解码峰值触顶，表现为开启 CFG 的请求延迟阶跃上升。其三，把少步蒸馏的画质结论外推到量化部署，材料未给出 NVFP4/FP8 实测，量化后的端点误差与画质下限无法从本文推断，表现为降档后画质投诉而非延迟投诉。</p>\n<p>监控侧应把端到端延迟拆成编码器段、学生前向段、解码段三段分别统计，并记录批大小、解码峰值、嵌入命中率与超时率。解码峰值与批大小的比值是判断是否该上分块解码的直接信号；学生前向段的单请求权重流量是判断批是否太小的信号；超时率上升而解码峰值未触顶，则瓶颈在排队或编码器段而非显存。调度器的降档动作应绑定到具体信号：解码峰值触顶降分辨率档或启用分块，排队延迟超阈值降步数档，两者不可混用同一个降档策略，否则会把显存问题误判为算力问题。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-26\">二十六 · 显存账本：解码峰值、CFG 翻倍与批大小的真实边界</h3>\n<p>这套方案里没有 KV cache 可算——学生一次前向就出端点潜变量，不存在自回归式的键值缓存增长。真正要算的是三笔账：权重常驻、学生前向的激活、以及 VAE 解码的峰值。设潜变量分辨率 $H_l\\times W_l$、潜通道 $C$、批大小 $B$、CFG 开启时有效批为 $2B$，则激活近似随 $B\\cdot H_l W_l C$ 线性增长，而解码输出张量随像素分辨率平方增长：</p>\n<div class=\"formula\">$$M_{\\text{peak}}\\approx M_{\\text{w}}+2B\\cdot M_{\\text{act}}(H_l,W_l)+\\underbrace{B\\cdot 3H_p W_p}_{\\text{解码输出与中间特征}}$$</div>\n<p>关键判断是：解码项往往先触顶。以潜空间 128×128（对应 1024² 像素档）为例，学生前向激活尚可容纳较大批，但解码阶段三通道像素图与上采样中间特征叠加，单样本占用远高于前向激活，批大小必须按解码峰值反推而非按学生前向估算——按前向显存定批会系统性高估容量，这是该方案最典型的失效条件。CFG 批合并把有效批翻倍，等于把解码峰值也翻倍，因此调度器必须把“是否合并 CFG”当作独立开关：合并摊薄权重读取、提升吞吐，但直接吃掉一半批容量。</p>\n<p>卸载与复用只能缓解不能消除。权重可常驻或按档位换入换出，文本编码器可与学生网络分时复用同一块显存；但解码峰值是瞬时量，卸载救不了峰值，只能靠降分辨率档、拆批或把解码放到独立流上串行化。分页式显存管理在此处的价值不在 KV，而在把变长分辨率的激活块按页分配，减少碎片导致的“账面上够、实际分配失败”。</p>\n<table class=\"mini\"><thead><tr><th>占用项</th><th>随什么增长</th><th>工程动作</th></tr></thead><tbody><tr><td>学生权重</td><td>固定</td><td>常驻，跨档位共享</td></tr><tr><td>前向激活</td><td>批大小 × 潜分辨率</td><td>聚批、分页分配</td></tr><tr><td>解码峰值</td><td>批大小 × 像素分辨率²</td><td>限批、拆批、降档</td></tr><tr><td>CFG 翻倍</td><td>×2</td><td>按 SLO 决定是否合并</td></tr></tbody></table>\n<p>带宽侧的压力同样落在解码：上采样与卷积反复读写特征图，HBM 流量随像素面积走，而学生前向只读一次权重、写一次端点潜变量，属算力受限而非带宽受限。因此在 Blackwell 档位上，量化权重能压常驻占用、放大可容纳批，但对解码峰值几乎无帮助；容量规划应以解码峰值为约束、以步数档位为调节阀，超时即降档换吞吐。</p>\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-27\">二十七 · 从“步数档位”到“批内异构”：连续批处理的粒度问题</h3>\n<p>潜一致性模型把单请求前向次数从教师的数十步压到个位数，服务侧的调度粒度随之改变：过去一个请求在队列里占用的“时间片”由采样步数决定，现在由档位决定。档位不是连续变量，1 步与少数步（如 2、4 步）之间的算力差距是成倍的，而画质差异又落在端点误差上。连续批处理要处理的正是这种批内异构：同一批里既有 1 步档位的低延迟请求，也有 4 步档位的高画质请求，学生网络对每个请求的前向次数不同，批的完成时间由最慢成员决定。</p>\n<p>工程上的做法是把“步”当作调度单元而非请求单元：调度器维护一个按档位分桶的就绪队列，每次组批时从同一档位取请求，批内步数一致，批间按到达顺序轮转。伪代码思路是：</p>\n<div class=\"formula\">$$\\text{batch}_k=\\{\\,r\\in Q_{\\text{tier}=k}\\mid \\text{count}\\le B_k\\,\\},\\quad B_k=\\min\\!\\left(B_{\\max},\\ \\left\\lfloor \\frac{M_{\\text{dec}}}{c\\cdot H\\cdot W} \\right\\rfloor\\right)$$</div>\n<p>其中 <span>M_dec</span> 是解码阶段可用的显存预算，<span>c</span> 是每像素解码的显存系数，<span>H·W</span> 是分辨率。这个约束说明批大小不是由学生前向决定的，而是由 VAE 解码的显存峰值决定的——解码阶段往往比学生前向更早触顶。代价是：高分辨率档位的批更小，权重读取摊薄不足，吞吐下降；低分辨率档位批大，但单请求延迟被批内排队拉长。连续批处理在这里的收益不是“更大批”，而是“不让 1 步请求等 4 步请求”，把档位隔离成独立的流水线。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-28\">二十八 · Chunked prefill 的类比：把 CFG 批合并拆成可抢占的块</h3>\n<p>LLM 侧的 chunked prefill 把长预填切成小块与解码请求混跑，避免长预填独占一个迭代。图像生成没有 KV cache，但有一个结构上类似的“长阶段”：CFG 批合并把条件与非条件前向拼成一个批，有效批翻倍，显存占用也翻倍。如果整批一次性送进学生网络，一个高分辨率请求的 CFG 批可能瞬间吃满显存，把同批的其他请求挤出去。</p>\n<p>可类比的机制是把 CFG 合并拆成两个可独立调度的子批：条件分支与非条件分支各自成块，调度器按显存余量决定是否合并。合并时吞吐高（一次前向算两路，权重读取摊薄一倍），但显存峰值翻倍；拆分时显存峰值减半，但前向次数翻倍、权重读取也翻倍。这个开关的取舍可以用一个简单的判据表达：</p>\n<div class=\"formula\">$$\\text{merge}=\\begin{cases}\\text{true}, &amp; 2\\cdot M_{\\text{cfg}}\\le M_{\\text{free}}\\ \\text{且}\\ \\lambda_{\\text{arrive}}\\cdot \\bar{t}_{\\text{fwd}} &gt; B_{\\text{split}}\\\\[4pt]\\text{false}, &amp; \\text{otherwise}\\end{cases}$$</div>\n<p>其中 <span>M_cfg</span> 是单路 CFG 分支的激活显存，<span>λ_arrive</span> 是到达率，<span>t̄_fwd</span> 是单次前向时间。判据的含义是：只有当显存允许且拆分后的批不足以吸收到达率时才合并。代价体现在尾延迟上——合并让批变大，批内最后一个请求的完成时间被拉长；拆分让批变小，但前向次数增加，单请求延迟的方差反而更小。对 SLO 敏感的服务，拆分是压尾延迟的手段。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-29\">二十九 · 优先级与抢占：超时请求的降档路径</h3>\n<p>潜一致性模型的一个直接工程优势是档位可降：1 步档位的端点误差大于 4 步档位，但前向次数少。当队列积压、某请求的端到端延迟逼近 SLO 上限时，调度器可以把它从 4 步档位抢占到 1 步档位，用画质换延迟。抢占的代价不是重算——学生一次前向就能给出端点，重算成本是一次前向加一次 VAE 解码，而不是从中间步恢复。这与 LLM 侧抢占需要重放 KV cache 完全不同：这里没有可复用的中间状态，抢占等价于丢弃当前批的进度、以更低档位重新组批。</p>\n<p>优先级设计要避免两个失败模式。其一是降档抖动：请求在 4 步与 1 步之间反复切换，每次切换都触发一次新的 VAE 解码，显存峰值反复冲高，反而拖慢同批请求。解法是给降档加迟滞——一旦降档，就在该请求的生命周期内锁定档位，不再回升。其二是降档误判：把显存峰值当成延迟信号。VAE 解码的显存峰值随分辨率平方增长，高分辨率请求即使队列不积压也可能因为解码显存不足而排队，此时降步数并不解决显存瓶颈，正确动作是降低批大小或把请求移到独立的高分辨率流水线。监控侧应把端到端延迟、批大小、显存峰值与超时率分开记录，才能区分“算力不够”与“显存不够”两类失败。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-30\">三十 · 分离式预填/解码的映射：学生前向与 VAE 解码分池</h3>\n<p>分离式预填/解码在 LLM 侧把计算密集的预填与访存密集的解码放到不同资源池。图像生成的对应结构是：学生一致性网络的前向是计算密集的（U-Net 卷积与注意力，权重读取为主），VAE 解码是显存密集且带宽敏感的（高分辨率特征图的上采样与卷积，激活显存随分辨率平方增长）。两者的资源画像不同，混在同一批里会让批大小被解码显存卡死，学生前向的算力利用率上不去。</p>\n<p>分池的做法是：学生前向池按激活显存组批，追求高 occupancy；解码池按解码显存峰值组批，追求显存不溢出。两池之间传递的是端点潜变量，数据量远小于像素图像，传输开销可忽略。代价是流水线气泡：前向池产出的潜变量要在解码池排队，如果解码池的吞吐低于前向池，潜变量会在中间缓冲里堆积，缓冲本身也占显存。容量规划时要让解码池的批处理能力匹配前向池的产出率，否则分离式部署只是把瓶颈从批大小搬到了队列长度。</p>\n<p>具体例子：一个高分辨率档位的请求，学生前向一次占用激活显存 <span>M_act</span>，VAE 解码占用 <span>M_dec</span>，且 <span>M_dec > M_act</span>。合池时批大小由 <span>M_dec</span> 决定，前向池的算力被浪费；分池后前向池可以组更大的批，解码池按 <span>M_dec</span> 单独组批，端到端吞吐由两池中较慢者决定。这个判断不需要实测数字，只需要比较两个显存项的量级——而材料明确指出解码显存峰值随分辨率平方增长，是高分辨率档位批大小的实际瓶颈。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-31\">三十一 · 尾延迟怎么压：批内同步点与解码抖动</h3>\n<p>尾延迟的来源在潜一致性模型服务里有两个：批内最慢成员的完成时间，以及 VAE 解码的显存抖动。前者由组批策略决定——把不同分辨率的请求混在一批，高分辨率成员的解码时间远长于低分辨率成员，整批等待它完成。后者由解码阶段的显存分配决定——解码显存峰值随分辨率平方增长，接近显存上限时分配器可能触发同步或碎片整理，表现为偶发的长尾。</p>\n<p>压尾延迟的手段是缩短批内同步点：把批按分辨率档位切分，同一批内分辨率一致，解码时间方差小；对跨档位的请求不做批合并，改用流水线重叠——低分辨率批在解码时，高分辨率批的前向已经开始。代价是批变小、权重读取摊薄不足，吞吐下降。这是一个明确的取舍：尾延迟与吞吐在批大小上是反向的，调度器要按 SLO 的百分位目标选择批大小，而不是按平均吞吐最大化。</p>\n<p>另一个手段是给解码阶段留显存余量。批大小按 <span>M_dec</span> 的某个比例（而非满额）设定，避免分配器在峰值附近抖动；余量本身浪费显存，但换来的是尾延迟的可预测性。对容量规划而言，这意味着有效批大小低于显存上限对应的理论批大小，容量估算不能按满额显存折算。材料未给出具体比例与实测尾延迟，工程判断只能落在机制上：解码显存峰值是批大小的硬约束，留余量是压尾延迟的必要代价。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-32\">三十二 · 调度器要记录什么：失败模式信号与档位决策</h3>\n<p>这套调度结构的可观测性要求比多步采样更高，因为档位、CFG 合并开关、分池策略都是运行时决策，任何一个决策错误都表现为 SLO 违约而非单请求报错。调度器至少要记录四类信号：每档的端到端延迟分布（不只是均值）、批大小与实际 occupancy、解码阶段显存峰值、超时率与降档次数。四类信号对应四种失败模式：延迟分布的长尾说明批内同步点过长；occupancy 低说明批大小被解码显存卡死；显存峰值贴近上限说明解码抖动风险高；降档次数上升说明档位策略与到达率不匹配。</p>\n<p>档位决策的逻辑应当是从信号到动作的映射，而不是固定阈值。例如：解码显存峰值持续贴近上限时，动作是降低批大小或启用 CFG 拆分，而不是降步数——降步数不减少解码显存。端到端延迟长尾且 occupancy 正常时，动作是切分分辨率档位，而不是增大批。超时率上升且显存有余量时，动作才是降档到更少步数。这个映射的关键在于区分“算力瓶颈”与“显存瓶颈”，而两者的信号在监控上是可分的：前者表现为前向池排队，后者表现为解码池排队。把这两类排队分开计数，是调度器做对档位决策的前提。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-33\">三十三 · 解码显存封顶下的档位调度与抢占边界</h3>\n<p>这套方案的调度器有一个与其他 LLM 服务不同的硬约束：批大小的上限不是由学生前向的激活显存决定，而是由 VAE 解码阶段的显存峰值决定。解码峰值随分辨率平方增长，在高分辨率档位上往往在学生前向还没触顶时就已经撞墙。因此调度器不能按“前向能塞多少”来聚批，而必须按 <span class=\"inline-math\">$B_{\\max}(r)=\\lfloor M_{\\text{free}}/c(r)\\rfloor$</span> 反推，其中 <span class=\"inline-math\">$c(r)$</span> 是分辨率 r 下单张图解码的显存占用，随 r 平方增长；CFG 批合并时有效批翻倍，这个上限还要再除以二。工程上的直接后果是：高分辨率档位的批远小于低分辨率档位，权重读取的摊薄效果差，吞吐被解码显存而非算力卡住。</p>\n<p>连续批处理在这里的形态与自回归解码不同——没有逐 token 的 KV 增长，请求的“长度”就是步数档位。调度器按分辨率与步数档位分组入队，同档聚批以摊薄固定开销；新请求只能在当前批的下一个前向边界插入，因为学生一次前向就产出端点潜变量，批内请求无法在中途换入。抢占的代价因此不对称：抢占一个已进入解码阶段的请求意味着丢弃其解码中间结果，重跑解码比抢占一个尚未前向的请求贵得多。合理的策略是只抢占排队中未前向的请求，对已进入解码的请求宁可等其完成。</p>\n<p>尾延迟的压缩依赖降档而非扩容。当队列积压时，调度器把请求从少数步档降到 1 步档以换取吞吐，代价是端点估计精度下降、画质上限受教师轨迹端点误差约束，步数越少误差累积越明显。监控侧记录每档的端到端延迟、批大小与显存峰值，超时请求进入降档或重试队列。分离式预填/解码在此处没有对应物——材料未给出 KV 类缓存与分离式部署的实测，文本编码与 VAE 解码是否值得拆到不同卡上，取决于解码显存峰值能否与编码侧解耦，这一点在 Blackwell 档位上无法从本文推断。</p>\n<table class=\"mini\"><thead><tr><th>档位</th><th>批大小约束</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>1 步</td><td>解码显存封顶，CFG 减半</td><td>端点误差累积，画质下限</td><td>高分辨率下批过小，吞吐不升</td></tr><tr><td>少数步</td><td>同上，前向次数增加</td><td>单请求算力线性上升</td><td>队列积压时尾延迟恶化</td></tr></tbody></table>\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-34\">三十四 · 从单卡少步前向到多卡切分：为什么一致性模型也要谈并行</h3>\n<p>潜一致性模型把学生前向压到个位数步，单请求算力随步数近似线性下降，但这一步只解决了“算得少”，没有解决“放得下、传得动”。高分辨率档位下，潜变量分辨率抬升使 U-Net 激活显存与 VAE 解码显存峰值同时上涨，后者随分辨率平方增长，往往比学生前向更早触顶。单卡容量一旦被解码峰值锁死，批大小就上不去，摊薄权重读取的收益消失，吞吐被显存而非算力卡住。此时把模型切开、把批切开、把条件与非条件分支切开，成为继续放大有效批的手段。并行的选择不是堆卡，而是先判断瓶颈落在哪一类资源上：激活与解码峰值落在显存，权重读取落在带宽，CFG 批合并落在有效批翻倍后的调度余量。Blackwell 档位上，SM100/SM103 的 tcgen05 与 TMEM 改变的是单卡算子内的数据通路，切分策略改变的则是卡间数据通路，两者代价模型不同，不能互相替代。</p>\n<p>对本工作而言，可切的维度有四类。数据并行（DP）复制学生权重、把批切成多份，切分后每卡激活显存按批比例下降，代价是每步一次梯度无关的权重同步——推理侧只在权重更新或档位切换时需要，稳态下几乎为零，因此 DP 是最先该用的手段。张量并行（TP）把 U-Net 的卷积与注意力通道切开，单层内做 All-Reduce，代价是每层两次集合通信，延迟随层数累积，适合单卡放不下单样本激活的极端分辨率档位。流水并行（PP）按 U-Net 的下采样—中间—上采样阶段切分，微批在阶段间流动，代价是流水气泡与阶段间点对点传输，对少步前向而言气泡占比高，收益有限。专家并行（EP）在扩散模型上并不对应 MoE 路由，而是把 CFG 的条件分支与非条件分支、或多分辨率档位分配到不同卡组，本质是分组调度而非权重切分，代价是组间负载不均。选择顺序应为 DP 优先、TP 兜底、PP 慎用、EP 仅用于分支隔离。</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\underbrace{\\frac{C_{\\text{layer}}}{N_{\\text{TP}}}}_{\\text{计算}}+\\underbrace{2\\,(N_{\\text{TP}}-1)\\,\\frac{S}{B_{\\text{nvlink}}}}_{\\text{All-Reduce}}+\\underbrace{\\frac{A_{\\text{act}}}{N_{\\text{DP}}\\,M_{\\text{free}}}}_{\\text{显存约束}}$$</div>\n<p>式中第一项是切分后的单层计算时间，第二项是 TP 组内 All-Reduce 的传输代价，S 为单层激活字节数，B 为链路带宽，第三项刻画 DP 把激活摊到多卡后对批大小的约束。举例：某高分辨率档位下单卡 VAE 解码峰值已接近容量上限，批只能取很小；改用 4 路 DP 后每卡解码峰值降到四分之一，批可放大数倍，端到端吞吐提升来自显存而非算力——这正是并行在少步推理里的真实收益位置。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-35\">三十五 · NVLink 5 与 NVSwitch：集合通信的物理底座</h3>\n<p>GB200/GB300 NVL72 机柜内以 NVLink 5 互联，配合 NVSwitch 构成全互联域，域内任意两卡之间可走单跳，这决定了 TP 组与 EP 组的拓扑上限。NVLink 5 的单链路带宽与聚合带宽是设计 TP 度数的硬约束：TP 度数越大，All-Reduce 的参与方越多，单层同步的字节数随度数增长，而链路带宽固定，于是通信时间随度数近似线性上升，计算时间随度数线性下降，两者交点就是该层的 TP 收益拐点。对 U-Net 这类层数多、单层计算量中等的结构，拐点通常出现在较小度数上，继续加大 TP 度数会让通信主导单步延迟。NVSwitch 的价值在于把跨卡通信从多跳降到单跳，使 All-to-All 这类非对称通信在机柜内可行；一旦 TP 组跨越机柜边界，链路降级为跨域互联，带宽与延迟同时恶化，少步前向的低延迟目标立刻失守。</p>\n<p>集合通信的两种形态在本工作里对应不同切分。All-Reduce 服务于 TP：每层切分后的部分和需要归约，环形或树形算法在 NVSwitch 全互联下可退化为单跳归约，代价是带宽受限而非跳数受限。All-to-All 服务于 EP 与分支隔离：CFG 批合并后条件与非条件分支若分置不同卡组，注意力层的键值需要按批重排，形成 All-to-All；多分辨率档位分组调度时，组间结果汇聚同样走 All-to-All。All-to-All 的代价对负载不均极其敏感，某一组卡少发或多发都会让其余组等待，形成木桶效应。工程判断是：能用 DP 与批内合并解决的，不要引入 All-to-All；必须引入时，先把各组负载配平，再谈带宽。</p>\n<table class=\"mini\"><thead><tr><th>切分</th><th>通信原语</th><th>触发频率</th><th>主要代价</th></tr></thead><tbody><tr><td>DP</td><td>权重同步（稳态近零）</td><td>档位切换/权重更新</td><td>显存下降，批可放大</td></tr><tr><td>TP</td><td>All-Reduce</td><td>每层每步</td><td>延迟随层数累积</td></tr><tr><td>PP</td><td>点对点</td><td>每微批阶段边界</td><td>流水气泡占比高</td></tr><tr><td>EP/分支隔离</td><td>All-to-All</td><td>注意力重排/组间汇聚</td><td>负载不均放大等待</td></tr></tbody></table>\n<p>具体例子：CFG 批合并把有效批翻倍，若把条件与非条件分支拆到两组卡上做 EP 式隔离，每组只算一半批，看似显存减半，但注意力层需要跨组交换键值，All-to-All 的字节数与批大小和序列长度成正比，交换时间可能超过省下的计算时间；而在同一卡内做批合并，代价只是显存翻倍，无跨卡通信。少步前向的总延迟本就短，通信占比被放大，因此分支隔离只在单卡显存确实放不下合并批时才值得。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-36\">三十六 · NIXL 传输：把显存与解码结果搬对地方</h3>\n<p>NIXL 面向的是推理链路中非集合通信的数据搬运：潜变量在编码器、学生网络、VAE 解码器之间的传递，跨节点或跨进程的批数据转运，以及分离式部署下预填与解码阶段之间的中间结果交接。对本工作，最值得用 NIXL 的位置是 VAE 解码的卸载：解码显存峰值随分辨率平方增长，若把解码放到独立卡组或独立节点，学生前向产出的端点潜变量需经 NIXL 传到解码侧，传输字节数为潜变量尺寸乘以批大小，与像素输出相比小得多，因此传输代价可控，而解码侧的显存压力被隔离，学生侧的批大小不再被解码峰值锁死。这是并行之外的另一条路：不改切分，改数据落点。</p>\n<p>NIXL 的代价模型是带宽与注册开销。传输本身走 NVLink 域内或跨节点网络，带宽决定搬运时间；显存注册与句柄建立有固定开销，小批高频传输会被固定开销主导，因此应把多个微批聚成一次传输，或让解码侧维持常驻缓冲。工程上要避免的是把 NIXL 当成零成本通道：端点潜变量虽小，但若每步每请求都触发一次传输，固定开销乘以请求数会显著抬高尾延迟。判断标准是单次传输字节数是否远大于注册开销对应的等效字节，否则应改为同卡解码或批内合并。</p>\n<div class=\"formula\">$$T_{\\text{xfer}}=\\frac{N_{\\text{batch}}\\cdot H\\cdot W\\cdot C\\cdot b_{\\text{latent}}}{B_{\\text{link}}}+T_{\\text{reg}},\\qquad T_{\\text{reg}}\\ \\text{按传输次数摊销}$$</div>\n<p>式中分子是潜变量总字节数，H、W 为潜空间分辨率，C 为通道数，b 为每元素字节；分母为链路带宽；后项为注册开销，按传输次数而非字节数计。举例：高分辨率档位下潜变量字节数远小于同档像素输出，把解码搬到独立卡组后，学生侧批大小可放大，代价是每批一次传输与解码侧常驻缓冲；若传输次数过多，注册开销会吃掉收益，此时应增大单次传输的批。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-37\">三十七 · 通信何时成为瓶颈：三个判据</h3>\n<p>第一个判据是单步计算时间与单步通信时间之比。少步前向把总步数压到个位数，单步内的层数不变，因此每层 All-Reduce 的固定延迟在总延迟中的占比被放大：教师数十步时通信可被计算掩盖，学生一步时通信无处可藏。若 TP 组内单层 All-Reduce 时间接近该层计算时间，继续加 TP 度数只会让延迟变差。第二个判据是有效批与显存的匹配：DP 把激活摊薄后批可放大，但批放大使每层激活字节数上升，All-Reduce 的传输量随批线性增长，于是通信时间随批增长而计算时间随批增长更慢，存在一个批大小使通信重新主导。第三个判据是负载均衡度：All-to-All 的完成时间由最慢参与方决定，CFG 分支隔离或多档位分组若负载不均，通信等待会被放大成尾延迟，监控上表现为批大小正常但端到端延迟抖动。</p>\n<p>把三个判据落到监控信号上：每档记录单步计算时间、集合通信时间、传输字节数与组间完成时间差。当集合通信时间占比越过阈值，应降低 TP 度数或改回 DP；当传输字节数随批增长快于计算时间，应停止放大批而转向解码卸载；当组间完成时间差持续存在，应先配平负载再谈带宽。这些信号与调度侧的降档逻辑联动：超时请求降档到更少步数时，单步计算时间下降但通信时间不变，通信占比进一步上升，降档未必能救回延迟，此时应优先减 TP 度数而非减步数。</p>\n<p>具体例子：某档位用 TP=8 切分 U-Net，单层计算被切到八分之一，但 All-Reduce 参与方为八，单层同步时间与计算时间同量级，单步延迟不降反升；改为 DP=8、TP=1 后，每卡算完整层但批被摊薄，稳态无集合通信，单步延迟回到计算主导，吞吐由显存决定。这个反例说明并行度数的选择要以通信占比为判据，而不是以卡数为判据。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-38\">三十八 · 与调度、解码的耦合：并行不是独立旋钮</h3>\n<p>并行切分与批调度、解码卸载三者共享同一份显存与带宽预算，调一个必然动另外两个。CFG 批合并使有效批翻倍，若同时开 TP，则 All-Reduce 的传输量按翻倍后的批计，通信时间翻倍；若改为分支隔离走 All-to-All，则交换字节数按批与序列长度计，代价更高。VAE 解码卸载走 NIXL 后，学生侧批可放大，但放大后的批使每层激活字节上升，TP 组内 All-Reduce 传输量随之上升，于是解码卸载释放的显存被通信时间吃掉一部分。工程判断的顺序是：先用 DP 与解码卸载把显存约束解开，再评估是否需要 TP；TP 只在单样本激活确实放不下时启用，且度数取到通信占比阈值以下为止；PP 与 EP 作为兜底，不进入常规档位。</p>\n<p>容量规划上，每档位应给出三个数：单卡可承载的最大批、该批下的单步计算时间与通信时间、解码侧常驻缓冲的显存占用。三者共同决定该档位的吞吐上限与尾延迟分布。材料未给出 NVFP4/FP8 量化与 Blackwell 档位的实测，因此量化后权重与激活字节数变化对通信量的影响无法从本文推断；但机制上，量化缩小传输字节会同时缩短 All-Reduce 与 NIXL 传输时间，对通信受限档位是直接收益，对计算受限档位收益有限。这一点应在档位验证时单独测量，而不是把量化当成普适加速。</p>\n<p>最后落在具体机制上：少步一致性模型把延迟预算压缩到个位数前向，通信不再是可被长计算掩盖的背景开销，而是与计算同量级的显式项。判断一个 Blackwell 档位是否该上 TP，看的不是模型多大，而是该档位下单层 All-Reduce 时间是否低于单层计算时间、批放大后传输量增长是否慢于计算增长、组间完成时间差是否可配平；三条同时满足才切，否则退回 DP 加解码卸载，把通信留在机柜内单跳域里，用显存换带宽。</p>\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-39\">三十九 · 精度塌陷：少步档位下的端点误差放大</h3>\n<p>潜一致性模型把采样压缩到个位数前向，代价是端点估计误差不再被多步迭代摊薄。失败模式的第一类不是崩溃，而是画质静默劣化：请求按时返回、图像结构大体成立，但细节纹理与文本一致性明显掉档。根因在训练点对——教师多步轨迹的相邻时间步构成约束，端点由教师的一步或少数步估计给出；步数越少，端点估计本身的偏差越大，一致性损失约束的是相邻点预测互相靠近，而非靠近真实端点，于是学生把教师的端点误差一并继承并放大。诊断上不能只看端到端延迟，必须把画质信号纳入监控：对固定提示词集做周期性抽检，比对少步档位与教师多步档位的端点潜变量距离，并统计 VAE 解码后的像素级差异分布。工程上把相邻时间步间隔与步数档位作为两个独立可调变量记录在请求元数据里，一旦某档位的端点距离统计量漂移超过阈值，就把该档位从调度池摘除，回滚到上一档步数配置。代价是明确的：档位回滚直接抬高单请求前向次数，队列延迟随步数近似线性上升，吞吐按同比例下降，这是用算力换画质的硬换算。</p>\n<div class=\"formula\">$$\\Delta_{\\text{endpoint}}=\\left\\|f_\\theta(\\mathbf{z}_{t_{n+1}},t_{n+1})-\\hat{\\mathbf{z}}_{t_n}\\right\\|_2,\\quad \\hat{\\mathbf{z}}_{t_n}=\\mathbf{z}_{t_{n+1}}-(t_{n+1}-t_n)\\,\\Phi(\\mathbf{z}_{t_{n+1}},t_{n+1})$$</div>\n<p>具体例子：某高分辨率档位把步数从少数步降到 1 步后，端点距离统计量在固定提示词集上整体上移，抽检图像出现局部结构重复；调度器按元数据定位到该档位，回滚到少数步配置，延迟回升但画质信号回到基线。注意这里没有实测数值可引用，判断依据只能是统计量的相对漂移方向，而非绝对阈值。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-40\">四十 · OOM：解码峰值而非前向峰值决定批大小</h3>\n<p>第二类失败是显存触顶。按学生前向的激活显存估算批大小是常见误判：学生一次前向的激活占用随潜变量分辨率与 U-Net 通道数增长，但真正先触顶的往往是 VAE 解码阶段，其显存峰值随分辨率平方增长。服务化链路是文本编码、CFG 批合并、学生少步前向、VAE 解码，前三个阶段的峰值可以靠分块或流式缓解，解码阶段的上采样特征图难以切分，于是批大小被解码峰值卡死。诊断路径：在请求元数据里分别记录学生前向峰值与解码峰值，按分辨率档位画出两条曲线，取二者较大者作为该档位的容量上限。CFG 批合并是第二个放大器——条件与非条件前向拼成一个批，有效批翻倍，若容量估算未计入这一倍，OOM 会在负载上升时集中爆发而非渐进出现。回滚手段是档位化的：高分辨率档位默认关闭 CFG 批合并或拆成两个微批串行，牺牲吞吐换稳定；同时把批大小上限写死在调度器配置里，禁止运行时按队列长度自适应放大。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>显存随分辨率的关系</th><th>是否可切分</th><th>容量估算角色</th></tr></thead><tbody><tr><td>学生少步前向</td><td>激活随分辨率增长</td><td>可分块</td><td>常被高估为瓶颈</td></tr><tr><td>CFG 批合并</td><td>有效批翻倍</td><td>可拆微批</td><td>容量估算的乘数项</td></tr><tr><td>VAE 解码</td><td>峰值随分辨率平方增长</td><td>难切分</td><td>实际批大小上限</td></tr></tbody></table>\n<p>具体例子：一个按学生前向峰值配置的批大小在中分辨率档位运行正常，切到高分辨率档位后解码阶段立即 OOM；把该档位批大小按解码峰值重算并关闭 CFG 合并，OOM 消失，代价是同档吞吐下降，调度器需把节省的显存折算回队列容量规划。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-41\">四十一 · 批抖动：聚批粒度与档位切换的耦合</h3>\n<p>第三类失败是批抖动——批大小在相邻调度周期之间大幅震荡，表现为吞吐锯齿与尾延迟尖峰。根因是聚批按分辨率与步数档位分组，档位切换（超时降档、画质回滚）会把请求从一个队列搬到另一个队列，原队列的批被拆散、新队列的批被稀释，摊薄权重读取的固定开销假设失效。诊断信号是批大小的时间序列方差与档位迁移率：迁移率高时，批填充率下降，单位请求的权重读取摊销变差，端到端延迟的分布尾部变厚。工程对策是把档位切换做成带滞回的：只有连续多个周期超时才降档，且降档请求进入独立的小批队列而非混入主队列；同时在监控侧记录每档的批填充率与迁移计数，作为容量规划的输入。代价是滞回引入的额外等待，尾延迟的改善以部分请求的延迟上界为代价。</p>\n<ul><li>监控项：批大小方差、档位迁移率、批填充率、每档端到端延迟分位数。</li><li>定位法：把尾延迟尖峰与迁移事件对齐，确认是拆批而非算力不足。</li><li>回滚法：关闭自动降档，固定档位配置，用队列长度而非超时触发扩容。</li></ul>\n<p>具体例子：超时降档策略在高负载下频繁触发，请求在少步档与少数步档之间来回迁移，两个队列的批都填不满，尾延迟反而高于不降档时；改为滞回加独立小批队列后，迁移率下降，批填充率回升，尾延迟分位数收敛。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-42\">四十二 · 尾延迟与静默降级：SLO 违约的两种面貌</h3>\n<p>第四类失败是尾延迟，第五类是静默降级，二者常同源。尾延迟来自批内最慢请求：CFG 批合并后批内同时含条件与非条件分支，解码阶段的长尾由分辨率最高的请求决定，低分辨率请求被迫等待同批的高分辨率解码完成。静默降级则是系统在压力下自动切到更少步数档位、关闭 CFG 合并或降低批大小，请求成功返回但画质与预期不符，且没有错误码。诊断静默降级的关键是把降档决策写入响应元数据：步数档位、CFG 是否合并、批大小，三者构成可追溯的降级指纹。监控侧按指纹分组统计延迟与画质抽检结果，一旦某指纹的占比在无发布变更的情况下上升，即判定为静默降级扩散。回滚手段是给降档加显式开关与配额：降档只允许在队列积压超过阈值时启用，且占比设上限，超过上限即触发告警而非继续降档。代价是积压期间部分请求被拒绝或排队更久，这是把静默劣化换成显式失败的取舍。</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{tail}}=\\Pr\\left[L_{\\text{e2e}}&gt;L_{\\text{target}}\\right],\\quad L_{\\text{e2e}}=L_{\\text{enc}}+L_{\\text{student}}+L_{\\text{decode}}$$</div>\n<p>具体例子：一次负载爬升中，降档占比悄然上升，端到端延迟分位数看起来达标，但画质抽检的端点距离统计量同步上移；按降级指纹分组后定位到 CFG 合并被关闭的批次，回滚该开关并限制降档配额，画质信号恢复，尾延迟分位数短暂变差后被容量扩容吸收。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-43\">四十三 · 监控面与回滚顺序：把失败模式映射到可执行动作</h3>\n<p>把五类失败模式收敛成一套监控面：延迟面记录端到端与各阶段分位数；显存面分别记录学生前向峰值与解码峰值；批面记录批大小、填充率与档位迁移率；画质面记录端点距离统计量与抽检差异；降级面记录步数档位、CFG 开关与降档占比。定位顺序按代价从低到高：先查降级指纹确认是否静默降级，再查批面确认是否抖动拆批，再查显存面确认是否解码触顶，最后查画质面确认是否精度塌陷。回滚顺序与之对应：先恢复 CFG 与步数档位配置，再固定批大小上限，再关闭自动降档，最后才动容量与硬件档位。每一步回滚都改变延迟与吞吐的换算关系，必须同步更新容量规划，否则回滚本身会制造新的尾延迟。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>首要信号</th><th>定位动作</th><th>回滚动作</th></tr></thead><tbody><tr><td>精度塌陷</td><td>端点距离统计量漂移</td><td>按步数档位分组比对</td><td>回滚步数档位</td></tr><tr><td>OOM</td><td>解码峰值触顶</td><td>分离前向与解码峰值曲线</td><td>降批大小、拆 CFG 微批</td></tr><tr><td>批抖动</td><td>批大小方差与迁移率</td><td>对齐尾延迟与迁移事件</td><td>滞回降档、独立小批队列</td></tr><tr><td>尾延迟</td><td>批内最慢请求拖尾</td><td>按分辨率分组看分位数</td><td>按分辨率分队列</td></tr><tr><td>静默降级</td><td>降级指纹占比上升</td><td>按指纹分组统计</td><td>限降档配额、显式告警</td></tr></tbody></table>\n<p>具体例子：一次发布后尾延迟分位数恶化，按上述顺序先查降级指纹未见异常，再查批面发现档位迁移率上升导致拆批，回滚滞回参数后批填充率恢复；整个过程未触碰步数与 CFG 配置，避免了不必要的画质回滚。这套顺序的价值在于把“先动哪个开关”从经验判断变成按信号代价排序的固定流程，而画质面的端点距离统计量始终是最后一道闸门——它不参与延迟优化，只负责在少步档位被过度使用时把系统拉回可接受的画质基线。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-44\">四十四 · 少步蒸馏服务化的失效边界与诊断回路</h3>\n<p>这套方案最危险的失效不是崩溃，而是“静默降级”：步数档位、CFG 合并、分辨率三者一旦错配，服务仍按 SLO 返回 200，但端点误差已经越过画质下限。端点误差随相邻时间步间隔放大，步数越少累积越明显，可写成端点漂移的粗略上界 <span class=\"formula\">$$\\|\\hat{\\mathbf{z}}_{\\text{end}}-\\mathbf{z}_{\\text{end}}\\|\\lesssim \\sum_{k}\\|\\Phi(\\mathbf{z}_{t_k},t_k)-\\Phi^{\\ast}(\\mathbf{z}_{t_k},t_k)\\|\\,(t_{k+1}-t_k)$$</span> 即每步求解器偏差乘以步长再求和。诊断上不能只看端到端延迟，必须在潜空间出口抽样比对教师多步端点（离线校准集），把该残差作为画质代理指标纳入监控；一旦某分辨率档的残差分布右移，就判定为精度塌陷而非性能问题，直接冻结该档的降档策略。</p>\n<p>OOM 与批抖动的根因几乎总是同一处：按学生前向激活显存估算批大小，而 VAE 解码峰值随分辨率平方增长，往往先触顶。工程上应把批大小约束写成 <span class=\"formula\">$$B_{\\max}=\\left\\lfloor \\frac{M_{\\text{free}}-M_{\\text{act}}(H,W)}{M_{\\text{dec}}(H,W)\\cdot(1+\\mathbb{1}_{\\text{CFG}})}\\right\\rfloor$$</span> 其中 CFG 批合并使有效批翻倍，是调度器最该显式建模的开关。批抖动表现为同一档位批大小在相邻调度周期反复跳变，进而拉高尾延迟：小批摊不薄权重读取，大批又触发解码峰值抖动。定位手段是记录每批的“实际批大小—显存峰值—解码耗时”三元组，若峰值方差与批大小强相关，说明该档应固定批而非动态聚批。</p>\n<p>尾延迟与静默降级的联动最隐蔽：超时请求被降档到更少步数重试，若降档后残差未被复核，等于用画质换 SLO 却不留痕。可维护一张按档位的诊断表，把失败模式与判据绑定。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>主判据</th><th>处置</th></tr></thead><tbody><tr><td>精度塌陷</td><td>潜空间端点残差右移</td><td>冻结降档，回滚到少数步档</td></tr><tr><td>OOM</td><td>解码峰值触顶而非前向激活</td><td>按分辨率平方重算批上限</td></tr><tr><td>批抖动</td><td>批大小方差与峰值强相关</td><td>该档固定批，停用动态聚批</td></tr><tr><td>尾延迟</td><td>降档重试占比升高</td><td>复核降档残差，回滚策略版本</td></tr></tbody></table>\n<p>回滚必须以“档位配置”为原子单位而非单请求：步数档、CFG 开关、批上限三者共享同一版本号，任何一项变更都触发离线残差校准再放量。材料未给出 NVFP4/FP8 量化与 Blackwell 档位实测，量化引入的数值偏差会直接叠加到端点残差上，因此量化上线前必须把残差监控阈值按量化档单独标定，不能沿用 FP16 基线；这也是该方案在具体硬件档位上仍需补齐的工程判断。</p>\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-45\">四十五 · 基准口径的三层结构：模型档、硬件档、服务档</h3>\n<p>读这篇工作的任何性能数字之前，必须先确认它落在哪一层口径上。第一层是模型档：教师潜扩散 U-Net 的参数量、潜变量分辨率、VAE 解码器的上采样倍率；第二层是硬件档：同一份学生权重在 B200 与 GB200 NVL72 上的 SM 数、HBM 容量与带宽、NVLink 5 拓扑完全不同，单卡与机架级部署的批上限不是同一个量；第三层是服务档：batch 上限、CFG 是否批合并、步数档位（1 步与少数步）、并发请求数与 SLO 目标。三层中任何一层变化，吞吐与延迟数字都不可直接横向比较。论文材料只给出机制性结论——采样从教师数十步压到个位数前向——并未给出数据集与硬件实测，因此本部分的任务不是复述数字，而是给出一个能判断“哪些提升可比、哪些不可比”的读法框架。</p>\n<p>具体机制上，把一次请求的端到端延迟拆成可加项是唯一能让口径对齐的做法：</p>\n<div class=\"formula\">$$T_{\\text{e2e}} = T_{\\text{enc}} + T_{\\text{cfg-batch}} + N_{\\text{step}}\\cdot T_{\\text{student}} + T_{\\text{vae}} + T_{\\text{queue}}$$</div>\n<p>其中 $N_{\\text{step}}$ 是步数档位，$T_{\\text{student}}$ 是单次学生前向的墙钟时间，$T_{\\text{vae}}$ 是解码时间，$T_{\\text{queue}}$ 是排队等待。少步蒸馏只压缩 $N_{\\text{step}}\\cdot T_{\\text{student}}$ 这一项；文本编码与 VAE 解码不随步数下降，队列项由调度策略决定。举例：若某档位下学生前向占总延迟的四成、VAE 解码占三成、编码与排队占三成，那么把步数从数十步降到个位数，端到端延迟的下降幅度远小于前向次数的下降幅度——这就是“步数压缩比”与“端到端加速比”不可互换的根本原因。工程判断上，报告任何加速比时必须同时给出该请求的延迟分解，否则读者无法判断加速来自步数还是来自批调度。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-46\">四十六 · batch 与并发的两种读法：静态聚批与连续批处理</h3>\n<p>扩散推理与自回归推理在批语义上有一个关键差别：自回归请求的 KV cache 随解码逐步增长，批内请求可以在不同步数上错峰进出；而扩散请求的批是一个同步整体，批内所有请求必须走完同一档步数才能一起解码。这意味着扩散服务的“并发”有两种完全不同的含义：静态聚批下的并发等于批大小，连续批处理下的并发等于在途请求数，后者可以远大于前者。论文材料给出的调度形态是按分辨率与步数档位聚批、超时降档，属于静态聚批加档位降级的组合，并未涉及连续批处理式的细粒度插入。</p>\n<p>代价核算上，批大小受两个上限夹逼：学生前向的激活显存与 VAE 解码的显存峰值。前者随批大小线性增长，后者随分辨率平方增长且与批大小线性相乘，因此高分辨率档位的批上限由解码阶段决定，而不是由学生网络决定。伪代码思路如下：</p>\n<ul>\n<li>对每个到达请求，按（分辨率, 步数档位）哈希入队；</li>\n<li>取队首档位，令 $B_{\\max}=\\min(B_{\\text{act}}, B_{\\text{vae}})$，其中 $B_{\\text{vae}}$ 由解码显存峰值反解；</li>\n<li>若 CFG 合并开启，有效批为 $2B$，需把 $B_{\\max}$ 折半后再聚批；</li>\n<li>聚批完成后一次性前向、一次性解码，整批延迟由最慢请求决定；</li>\n<li>队列积压超过阈值时，把新请求降档到更少步数，换取更高吞吐。</li>\n</ul>\n<p>具体例子：同一张高分辨率图，CFG 合并开启时显存占用翻倍，若不把批大小折半，解码阶段会先于学生前向触顶，表现为批内部分请求 OOM 重试，端到端延迟反而上升。这就是“吞吐提升不可比”的典型场景——两个报告都写“吞吐提升”，一个是在 CFG 关闭、批大小翻倍下取得，另一个是在 CFG 开启、批大小折半下取得，二者的显存预算与 SLO 违约率完全不同。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-47\">四十七 · 指标族：TTFT/TPOT 在扩散服务里的映射与失真</h3>\n<p>TTFT（首 token 时间）与 TPOT（每 token 时间）是为自回归解码定义的指标，直接搬到扩散服务会失真。扩散请求没有 token 流，只有“首帧可用时间”与“整图完成时间”。可用的映射是：把 TTFT 类比为从请求入队到潜变量端点产出（即学生前向完成）的时间，把 TPOT 类比为 VAE 解码的分块进度，但后者并不是逐 token 可观测的。工程上更稳的做法是直接报告三个量：排队延迟、学生前向墙钟、解码墙钟，再合成端到端延迟。论文材料给出的监控项是端到端延迟、批大小与显存峰值，这与上述分解一致，但没有给出 TTFT/TPOT 式的细粒度指标。</p>\n<p>吞吐的口径同样需要钉死：是每秒完成请求数（RPS），还是每秒产出像素数（pixels/s），还是每秒学生前向次数。三者在小批量高分辨率下差异巨大。举例：批大小从 1 提到 4，RPS 可能提升接近四倍，但 pixels/s 的提升受解码带宽限制而明显更小；若再叠加 CFG 合并，有效批翻倍而显存翻倍，RPS 的提升会被 OOM 重试率抵消一部分。显存指标要区分峰值与稳态：学生前向的激活显存是瞬态峰值，VAE 解码的显存峰值随分辨率平方增长且持续时间更长，容量规划应按解码峰值留余量。功耗指标在材料中未给出，Blackwell 档位上的功耗与时钟行为需实测，不能从步数压缩比推断。</p>\n<table class=\"mini\">\n<thead><tr><th>指标</th><th>口径定义</th><th>受什么影响</th><th>可比性判断</th></tr></thead>\n<tbody>\n<tr><td>端到端延迟</td><td>入队到图像回传</td><td>步数档位、批大小、队列深度</td><td>同档位同批大小下可比</td></tr>\n<tr><td>学生前向墙钟</td><td>单次前向完成时间</td><td>分辨率、批大小、精度</td><td>跨硬件档不可比</td></tr>\n<tr><td>解码墙钟</td><td>VAE 解码完成时间</td><td>分辨率平方、批大小</td><td>跨分辨率不可比</td></tr>\n<tr><td>RPS</td><td>每秒完成请求数</td><td>批大小、CFG 开关、降档率</td><td>须注明 CFG 与档位</td></tr>\n<tr><td>显存峰值</td><td>解码阶段峰值占用</td><td>分辨率平方、批大小、CFG</td><td>按解码峰值而非前向峰值</td></tr>\n</tbody>\n</table>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-48\">四十八 · 哪些提升不可比：四类典型误读</h3>\n<p>第一类是把步数压缩比当作端到端加速比。材料明确：单请求前向次数近似线性下降，但文本编码与 VAE 解码不随步数下降，队列延迟由调度决定。因此“前向次数降一到两个数量级”不能换算成“端到端延迟降一到两个数量级”。第二类是把画质结论跨分辨率外推。少步蒸馏的端点误差由教师轨迹端点估计精度约束，步数越少误差累积越明显；在高分辨率潜空间上，端点误差经 VAE 解码后被放大，材料未给出对应实测，因此低分辨率下的画质结论不能直接搬到高分辨率档位。</p>\n<p>第三类是跨硬件档比较吞吐。B200 单卡与 GB200 NVL72 机架级的显存容量、NVLink 5 带宽与批上限完全不同，同一份学生权重在两档上的最优批大小不同，RPS 不可直接对比；材料未给出 Blackwell 档位实测，任何跨档数字都属外推。第四类是忽略 CFG 开关对有效批的影响。CFG 批合并使有效批翻倍，显存与延迟预算须同步翻倍；若两个报告一个开 CFG 一个关 CFG，其吞吐数字不在同一口径上。工程判断上，看到任何加速比先问三件事：步数档位是多少、CFG 是否合并、批大小与分辨率是多少；三者缺一，数字不可采信。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-49\">四十九 · 容量规划的读法：从解码峰值反解批上限</h3>\n<p>容量规划的正确起点不是学生前向的激活显存，而是 VAE 解码的显存峰值。材料明确指出解码阶段往往比学生前向更早触顶，且峰值随分辨率平方增长。因此给定硬件档的可用显存 $M_{\\text{avail}}$（扣除权重、文本编码器与运行时开销），批上限可近似反解为：</p>\n<div class=\"formula\">$$B_{\\max} \\approx \\left\\lfloor \\frac{M_{\\text{avail}} - M_{\\text{static}}}{M_{\\text{vae}}(H,W) + M_{\\text{act}}(B)}\\right\\rfloor$$</div>\n<p>其中 $M_{\\text{vae}}(H,W)$ 是单请求解码峰值、$M_{\\text{act}}(B)$ 是学生前向的每批激活增量。这个式子说明两件事：分辨率翻倍时 $M_{\\text{vae}}$ 按平方增长，批上限急剧收缩；CFG 合并时有效批翻倍，等价于把 $B_{\\max}$ 折半。具体例子：某高分辨率档位下单请求解码峰值已占可用显存的可观比例，此时批大小只能取很小值，吞吐由解码带宽而非学生前向算力决定——这正是“少步蒸馏省下的算力被解码瓶颈吃掉”的服务化现实。容量规划应按最坏分辨率档位留解码余量，并按档位分别给出批上限，而不是给一个全局批大小。</p>\n<p>监控侧的失败模式信号也应围绕这条反解式设计：记录每档的批大小、解码显存峰值、端到端延迟与超时率；当解码峰值接近可用显存时触发降档或减小批，当超时率上升时触发步数降档。材料给出的监控项与此一致，但未给出具体阈值，阈值需按硬件档与 SLO 实测标定。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-50\">五十 · 量化与 Blackwell 档位：材料未覆盖的部分如何标注</h3>\n<p>论文材料明确未给出 NVFP4/FP8 量化、KV 类缓存与分离式预填解码的实测，因此本部分不能给出任何 Blackwell 档位上的数值精度与容量结论。可做的只是标注口径缺口：少步蒸馏把前向次数压到个位数后，单次前向的权重读取占比上升，量化对带宽的节省在少步档位下的边际收益与多步档位不同；NVFP4 的块缩放与 FP8 的 per-tensor 缩放在学生 U-Net 的激活分布上是否稳定，材料未验证，不能从教师模型的量化经验外推。工程判断上，任何声称“在 B200 上把该模型量化到 NVFP4 后吞吐提升”的数字，若未同时给出画质指标（端点误差或人工评估）与解码显存峰值，就属于不可比的口径——因为量化可能改变学生前向的显存占用，从而改变批上限，而批上限的变化又会反过来改变吞吐，三者耦合，不能单独归因于量化。</p>\n<p>落到具体机制上：在少步档位下，学生前向的墙钟已不是端到端延迟的主导项，量化带来的前向加速会被解码与排队稀释；因此量化在 Blackwell 档位上的收益应优先按“是否抬高批上限”来评估，而不是按“单次前向快了多少”来评估。这一判断直接决定容量规划时把预算投在解码侧还是前向侧——材料给出的机制性结论是解码峰值先触顶，因此解码侧的显存优化（分块解码、降低解码批）比前向侧的算力优化更能抬高吞吐上限。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-51\">五十一 · 基准口径的失效边界：少步蒸馏数字在什么条件下不可比</h3>\n<p>读这篇工作的性能数字，第一件事是确认口径落在哪一层。材料只给出机制性结论：学生一次前向把噪声潜变量映射到轨迹端点，采样步数从教师数十步降到个位数，单请求前向次数近似线性下降。这个“线性”只对前向次数成立，不对端到端延迟成立——延迟由文本编码、CFG 批合并、学生前向、VAE 解码四段串联，步数压缩只砍掉其中一段。若把教师多步的端到端延迟与学生少步的端到端延迟直接相除，得到的倍数会被固定开销稀释；正确口径是分别报各段耗时与批大小，再折算单请求算力。跨硬件档位比较时，B200 与 GB200 NVL72 的显存带宽与功耗包络不同，同一 batch 下的 TTFT/TPOT 不可直接对齐，只能比“每档步数下的显存峰值是否触顶”这类结构性结论。</p>\n<p>第二件事是分辨哪些提升来自步数、哪些来自批调度。CFG 批合并把条件与非条件前向拼成一个批，有效批翻倍：吞吐上去的同时显存占用也翻倍，这是调度器的开关而非算法收益。设有效批为 <span class=\"formula\">$$B_{\\mathrm{eff}}=B\\cdot(1+\\mathbb{1}_{\\mathrm{CFG}})$$</span>，则显存峰值近似 <span class=\"formula\">$$M_{\\mathrm{peak}}\\approx M_{\\mathrm{act}}(B_{\\mathrm{eff}},H,W)+c\\,H\\,W\\,B_{\\mathrm{eff}}$$</span>，第二项是 VAE 解码随分辨率平方增长的占用。高分辨率档位往往在解码段先触顶，此时按学生前向显存估容量会系统性高估可承载批大小，这是最典型的不可比来源。</p>\n<table class=\"mini\"><thead><tr><th>口径变量</th><th>可比条件</th><th>不可比情形</th></tr></thead><tbody><tr><td>步数档位</td><td>同档位、同 CFG 开关</td><td>1 步与少数步混报，端点误差不同</td></tr><tr><td>批大小</td><td>同分辨率、同显存峰值</td><td>CFG 合并前后有效批翻倍</td></tr><tr><td>硬件档位</td><td>同功耗包络下的结构性结论</td><td>跨 B200/GB200 直接比 TPOT</td></tr><tr><td>指标</td><td>分段报 TTFT/解码/端到端</td><td>只报总吞吐，掩盖解码瓶颈</td></tr></tbody></table>\n<p>第三件事是量化与数值精度。材料明确未给出 NVFP4/FP8 实测，因此任何“少步 + 低精度”叠加后的画质与吞吐结论都不能从本文外推：一致性损失的端点误差在低精度激活下会被放大，步数越少误差累积越明显，而这条链路在 Blackwell 上的数值行为需另行验证。工程判断应落在可监控的量上——按分辨率与步数档位聚批，记录每档的端到端延迟、批大小、显存峰值与超时率，超时即降档到更少步数或重试；把 VAE 解码显存峰值作为容量规划的第一约束，而不是学生前向的激活占用。</p>\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-52\">五十二 · 迁移到非 U-Net 骨干：一致性约束的可加性</h3>\n<p>这套方案在结构上有一个隐含前提：学生复用教师骨干，且骨干在潜空间上做的是“输入带噪潜变量 + 时间步、输出去噪方向”的映射。一致性蒸馏只约束相邻两点的输出指向同一端点，因此它对骨干的具体形态并不敏感，但对“时间步如何进入网络”极其敏感。迁到 DiT 类骨干时，时间步通常以 adaLN 调制或 token 拼接方式注入，相邻时间步的间隔在嵌入空间里被放大或压缩，教师轨迹上相邻点的端点估计误差会随调制方式改变。工程上要改的第一件事是时间步采样策略：不能沿用 U-Net 时代的均匀或对数间隔，而应按骨干对时间步的敏感度重新标定相邻点间隔，否则一致性损失在早期时间步上梯度方向不稳。</p>\n<p>代价体现在训练显存与收敛速度上。DiT 类骨干的激活显存随 token 数线性增长，而潜变量分辨率不变时 token 数由 patch size 决定，patch 越小激活越大。学生一次前向的激活峰值直接决定训练批大小，进而决定相邻点对的采样密度。若把 patch size 减半以提升画质，激活显存翻数倍，批大小被迫压缩，点对覆盖不足会让端点误差在少步档位上暴露。迁移判断：骨干换成 DiT 可行，但必须重标定时间步间隔与 patch size 的组合，并把训练批大小当作一等约束而非事后调参。</p>\n<div class=\"formula\">$$\\Delta t_{\\text{eff}} = \\left\\| \\tau(t_{n+1}) - \\tau(t_n) \\right\\|_2,\\quad \\text{其中 } \\tau(\\cdot) \\text{ 为骨干的时间步嵌入映射}$$</div>\n<p>具体例子：同一潜空间分辨率下，U-Net 骨干的相邻点间隔可按固定比例取，迁到 adaLN 调制的 DiT 后，若仍按原比例取点，早期时间步的嵌入差异过小，学生预测几乎重合，一致性损失退化，少步档位在低噪声段出现结构崩坏。此时应把间隔改为按嵌入距离自适应取点，代价是每条轨迹要多算若干次教师前向以估计嵌入距离，训练侧算力上升，但推理侧步数档位不变。</p>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-53\">五十三 · 迁到流匹配与整流采样器：端点定义的改写</h3>\n<p>一致性蒸馏的公式里，端点由教师的多步求解器给出，而相邻点的预测通过减去速度场乘时间差得到。这套写法在扩散的得分匹配框架下成立，迁到流匹配或整流采样器时，速度场的语义从“得分函数的缩放”变成“概率流的速度”，相邻点关系仍是线性外推，但端点估计的误差结构不同。流匹配的轨迹在时间轴上更接近直线，相邻点间隔可以取得更大而不破坏自一致，这意味着少步档位可以更激进；代价是端点估计对教师求解器的步长更敏感，教师步长稍大就会让端点偏离真实流线，学生学到的映射在少步时偏向平均路径而非真实端点。</p>\n<p>工程上要改的是教师轨迹的构造方式：不能只取相邻两点，而要在同一轨迹上取多点并用局部线性拟合估计端点，把端点误差从单步外推误差降到拟合残差。训练侧代价是每条轨迹的教师前向次数增加，训练吞吐下降；推理侧收益是少步档位的画质下限抬高。判断：流匹配骨干上这套方案更划算，因为直线化轨迹让少步蒸馏的误差累积更慢，但必须把端点估计从单步外推改为局部拟合，否则少步档位的画质波动会直接传导到服务 SLO。</p>\n<ul>\n<li>机制：端点由教师多步求解器给出，流匹配下轨迹直线化，相邻点间隔可放大。</li>\n<li>公式：端点误差随教师步长增大而增大，局部拟合把误差压到拟合残差量级。</li>\n<li>代价：训练侧教师前向次数上升，训练吞吐下降；推理侧步数档位不变或更少。</li>\n<li>例子：教师步长取大值时，单步外推端点在弯曲轨迹上偏离，少步学生输出出现纹理模糊；改用三点拟合后端点回正。</li>\n</ul>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-54\">五十四 · 迁到视频与多帧生成：时间维的一致性约束</h3>\n<p>视频扩散把潜变量从二维扩展到三维，时间维引入后，一致性约束不能只在单帧的相邻时间步上做，否则帧间一致性无人约束，少步生成会出现闪烁。迁移时要改的是点对构造：同一轨迹上取相邻时间步的两点，同时在时间维上取相邻帧的两点，把一致性损失扩展为时空联合约束。代价是学生一次前向的输出从单帧潜变量变成多帧潜变量，激活显存随帧数线性增长，批大小被进一步压缩；而 VAE 解码的显存峰值在视频上随分辨率平方乘帧数增长，解码阶段比学生前向更早触顶的问题被放大。</p>\n<p>工程判断：视频场景下这套方案的步数压缩收益仍在，但批调度必须按帧数分档，短片段与长片段不能混批，否则长片段解码显存峰值会拖垮整批。CFG 批合并的开关在视频上更敏感，有效批翻倍后解码显存直接越界，通常要在视频档位关闭合并或把条件与非条件分两次前向以时间换显存。具体例子：同一分辨率下，单帧图像档位可开 CFG 合并，视频档位若沿用合并，解码显存峰值超出单卡容量，调度器被迫把批大小降到一，吞吐塌陷；改为分两次前向并把结果在潜空间拼接，显存回到预算内但端到端延迟上升，需在 SLO 里显式计入。</p>\n<div class=\"formula\">$$M_{\\text{dec}} \\propto H \\cdot W \\cdot F \\cdot C,\\quad \\text{批大小 } B \\le \\frac{M_{\\text{budget}}}{M_{\\text{dec}}}$$</div>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-55\">五十五 · 迁到量化部署：数值精度与一致性损失的耦合</h3>\n<p>材料未给出量化实测，但迁移判断可以定性给出：一致性损失约束的是相邻点预测之间的距离，这个距离在低精度下会被量化噪声污染。NVFP4 的块缩放把权重与激活压到四位，量化误差在相邻时间步的预测上不完全相关，一致性损失会把部分量化噪声当成信号去拟合，导致学生学到的映射在少步档位上偏向噪声平均而非真实端点。工程上要改的是训练时的量化感知：在一致性损失计算前对预测做与推理一致的量化模拟，让损失看到量化后的距离，而不是全精度距离。</p>\n<p>代价分两侧：训练侧量化模拟增加激活显存与算力，批大小进一步压缩；推理侧四位权重让权重读取带宽下降，学生前向的访存瓶颈缓解，但 VAE 解码仍以全精度或半精度运行，解码显存峰值不变，批大小瓶颈仍在解码侧。判断：量化对这套方案的收益主要在学生前向的权重带宽上，对解码显存无解；若把量化误差计入一致性损失，少步档位的画质下限可守住，但训练成本上升，需在画质与训练吞吐间取舍。具体例子：四位权重下学生前向延迟下降，但若不做量化感知训练，少步档位输出出现块状伪影，调度器监控到的超时率上升，触发降档反而抵消了量化收益。</p>\n<ul>\n<li>机制：一致性损失在量化噪声下失真，需在损失前做量化模拟。</li>\n<li>代价：训练侧激活显存与算力上升；推理侧权重带宽下降但解码显存不变。</li>\n<li>判断：量化收益在学生前向，解码侧瓶颈不因量化缓解。</li>\n</ul>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-56\">五十六 · 规模上限：步数下限与分辨率上限</h3>\n<p>这套方案的规模上限由两个独立约束夹住。步数下限由端点估计精度决定：步数越少，相邻点间隔越大，端点外推误差越大，一致性损失能压到的画质下限越高。一步映射在低分辨率上可行，但高分辨率下潜变量的高频细节对端点误差更敏感，一步档位的画质下限会先于低分辨率档位触顶。分辨率上限由 VAE 解码显存峰值决定，峰值随分辨率平方增长，解码阶段往往比学生前向更早触顶，批大小被迫降到一，吞吐随分辨率上升而塌陷。</p>\n<p>工程判断：这套方案的适用区间是“中高分辨率 + 个位数步数”，一步档位只在低分辨率或画质容忍度高的场景成立；分辨率继续上升时，瓶颈从学生前向转移到解码，此时应把优化重心放在解码侧的分块与低精度解码，而不是继续压步数。具体例子：同一模型在分辨率翻倍后，学生前向延迟近似不变，但解码显存峰值翻四倍，批大小从多降到一，端到端吞吐下降远超过步数压缩带来的收益，调度器只能把高分辨率请求单独排队，队列延迟成为主要 SLO 风险。</p>\n<div class=\"formula\">$$T_{\\text{e2e}} \\approx T_{\\text{enc}} + \\frac{T_{\\text{student}}}{B} + \\frac{T_{\\text{dec}}(H,W)}{B},\\quad B \\le \\min\\left(B_{\\text{student}}, B_{\\text{dec}}\\right)$$</div>\n\n<h3 id=\"paper-latent-consistency-models-synthesizi-2023-sec-57\">五十七 · 不适用的边界：何时不该用这套方案</h3>\n<p>有三类场景不适合直接套用。第一类是教师轨迹本身不稳定或端点估计不可靠的场景，比如教师模型在特定条件上多步采样方差大，相邻点对的端点估计噪声大，一致性损失学到的映射在少步时放大噪声，画质不可控。第二类是请求形态以极低延迟单发为主、批调度无法聚批的场景，这套方案的收益来自步数压缩摊薄固定开销，单发请求下批大小为一，步数压缩的吞吐收益无法兑现，反而因学生网络额外的前向开销拖慢延迟。第三类是画质要求接近教师多步输出的场景，少步蒸馏的画质上限受端点误差约束，无法达到教师数十步的画质，强行使用会在验收环节失败。</p>\n<p>判断依据应落在可观测信号上：监控端到端延迟、批大小、显存峰值与超时率，若批大小长期为一且超时率随分辨率上升，说明聚批失效，应回到教师多步或换调度策略；若少步档位的画质验收不通过，说明端点误差超出容忍度，应提高步数档位或改用局部拟合端点估计。具体例子：单发低延迟场景下，学生一步前向的固定开销与教师一步前向相近，步数压缩无收益，调度器观察到批大小恒为一、队列延迟不降，此时应关闭少步档位，把请求路由到教师多步路径以保画质。</p>\n<ul>\n<li>机制：收益依赖聚批摊薄固定开销，单发场景下失效。</li>\n<li>代价：学生额外前向开销在批大小为一的时候直接体现为延迟上升。</li>\n<li>判断：以批大小与超时率为信号决定是否启用少步档位。</li>\n</ul>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Latent Consistency Models:</text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\"> Synthesizing…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2023 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Latent Consistency Mode… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>未给出</td></tr><tr><td>基线</td><td>教师潜扩散模型多步采样、像素空间一致性模型</td></tr><tr><td>主要结果</td><td>材料未给出具体数据集与数值；可核验的机制性结论是把采样从教师的多步迭代压到…</td></tr><tr><td>消融</td><td>材料未给出系统消融；可推断的关键变量为相邻时间步间隔、学生目标网络滑动平均…</td></tr><tr><td>局限</td><td>少步蒸馏的画质上限受教师轨迹端点估计精度约束，步数越少误差累积越明显；高分…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-latent-consistency-models-synthesizi-2023 · 共 9 个片段</p>\n";break;}}})();
